/* ===== Flashcard · Hướng dẫn viết – HSK3 Bài 1–17 =====
   [mẹo nhớ theo bộ thủ, [câu ví dụ, pinyin, nghĩa]]. Câu ví dụ dùng từ HSK1–2 và các bài HSK3 đã học. */
var WG=Object.assign(window.WG||{},{
"3-1":{
"以为":["以: người cầm dụng cụ làm việc → dùng, lấy. 为 (vi): làm, cho là. 以为 = tự cho là, tưởng là (thường là tưởng sai).",["我以为你是老师。","Wǒ yǐwéi nǐ shì lǎoshī.","Mình cứ tưởng bạn là giáo viên."]],
"像":["Bộ <b>亻</b> (nhân – người) + 象 (con voi, hình ảnh): người có hình dáng như hình mẫu → giống.",["你长得很像你妈妈。","Nǐ zhǎng de hěn xiàng nǐ māma.","Bạn trông rất giống mẹ bạn."]],
"长":["Chữ đa âm: đọc <b>zhǎng</b> = lớn lên (长得: trông), đọc <b>cháng</b> = dài. Nét ngang dài như mái tóc dài.",["孩子长得很快。","Háizi zhǎng de hěn kuài.","Trẻ con lớn rất nhanh."]],
"身高":["身: hình người có cái bụng → thân thể. 高: hình tòa nhà nhiều tầng → cao. Chiều cao của thân người.",["他身高一米七。","Tā shēngāo yì mǐ qī.","Anh ấy cao một mét bảy."]],
"米":["Hình bông lúa với các hạt gạo tỏa ra 4 phía → gạo. Còn mượn để chỉ “mét”. Chữ có bộ 米 thường liên quan đến lương thực: 粉, 糕.",["我家离学校一千米。","Wǒ jiā lí xuéxiào yìqiān mǐ.","Nhà mình cách trường một nghìn mét."]],
"瘦":["Bộ <b>疒</b> (nạch – bệnh) + 叟: người ốm bệnh thì gầy đi. Chữ có 疒 thường liên quan đến bệnh: 病, 疼.",["你最近瘦了。","Nǐ zuìjìn shòu le.","Dạo này bạn gầy đi rồi."]],
"接":["Bộ <b>扌</b> (thủ – tay) + 妾: đưa tay ra đón lấy → đón, nhận.",["我去机场接朋友。","Wǒ qù jīchǎng jiē péngyou.","Mình ra sân bay đón bạn."]],
"行李":["行: ngã tư đường → đi. 李: cây mận (木 + 子), đọc nhẹ “li”. Đồ mang theo khi đi đường = hành lý.",["你的行李多吗？","Nǐ de xíngli duō ma?","Hành lý của bạn có nhiều không?"]],
"丢":["Chữ 去 (đi) thêm một nét phẩy ở trên: đồ vật “đi mất” → làm mất.",["我的手机丢了。","Wǒ de shǒujī diū le.","Điện thoại của mình bị mất rồi."]],
"箱子":["箱 có bộ <b>⺮</b> (trúc – tre) + 相: hòm ngày xưa đan bằng tre → hòm, va li. 子 đọc nhẹ “zi”.",["这个箱子太重了。","Zhège xiāngzi tài zhòng le.","Cái va li này nặng quá."]],
"号码":["号: miệng 口 hô to → số hiệu. 码 có bộ <b>石</b> (thạch – đá) + 马 gợi âm mǎ: con số, mã số.",["你的电话号码是多少？","Nǐ de diànhuà hàomǎ shì duōshao?","Số điện thoại của bạn là bao nhiêu?"]],
"好像":["好 (tốt) + 像 (giống, bộ <b>亻</b>): trông giống như → dường như, hình như.",["外面好像下雨了。","Wàimiàn hǎoxiàng xià yǔ le.","Bên ngoài hình như mưa rồi."]],
"重要":["重: vật nặng trên mặt đất → nặng, nặng ký. 要: cần. Nặng ký và cần thiết → quan trọng.",["这件事很重要。","Zhè jiàn shì hěn zhòngyào.","Việc này rất quan trọng."]],
"着急":["急 có bộ <b>心</b> (tâm) ở dưới: trong lòng nóng như lửa → gấp, lo. 着 ở đây đọc <b>zháo</b>.",["别着急，我们慢慢找。","Bié zháojí, wǒmen mànmàn zhǎo.","Đừng lo, mình từ từ tìm."]],
"护照":["护 có bộ <b>扌</b> (tay) che chở → bảo vệ. 照 có bộ <b>灬</b> (lửa) → chiếu, soi. Giấy tờ bảo vệ người đi nước ngoài = hộ chiếu.",["请给我看一下你的护照。","Qǐng gěi wǒ kàn yíxià nǐ de hùzhào.","Vui lòng cho tôi xem hộ chiếu của bạn."]],
"服务台":["服务: phục vụ (务 có bộ 力 – sức lực, bỏ sức làm việc). 台: cái bục, quầy. Quầy phục vụ.",["你去服务台问问吧。","Nǐ qù fúwùtái wènwen ba.","Bạn ra quầy phục vụ hỏi thử đi."]],
"应该":["应 có bộ <b>广</b> (nghiễm – mái nhà) + 心 nằm dưới. 该 có bộ <b>讠</b> (lời nói): điều đáng nói → nên, chắc là.",["你应该多休息。","Nǐ yīnggāi duō xiūxi.","Bạn nên nghỉ ngơi nhiều hơn."]],
"站":["Bộ <b>立</b> (lập – người đứng thẳng trên mặt đất) + 占 gợi âm: đứng. Cũng có nghĩa “trạm, ga”.",["他站在门口。","Tā zhàn zài ménkǒu.","Anh ấy đứng ở cửa."]],
"中间":["中: đường thẳng xuyên qua giữa ô vuông → giữa. 间: mặt trời 日 nằm giữa hai cánh cửa 门 → khoảng giữa.",["我坐在他们中间。","Wǒ zuò zài tāmen zhōngjiān.","Mình ngồi giữa họ."]],
"短":["Bộ <b>矢</b> (thỉ – mũi tên) + 豆: ngày xưa lấy mũi tên để đo vật ngắn → ngắn. Trái nghĩa với 长 cháng.",["她的头发很短。","Tā de tóufa hěn duǎn.","Tóc cô ấy rất ngắn."]],
"头发":["头: cái đầu. 发: ở đây là sợi tóc, đọc nhẹ “fa”. Tóc mọc trên đầu.",["你的头发真长。","Nǐ de tóufa zhēn cháng.","Tóc bạn dài thật."]],
"年轻":["年: năm, tuổi. 轻 có bộ <b>车</b> (xa – xe): xe nhẹ → nhẹ. Tuổi còn “nhẹ” = trẻ.",["我们的老师很年轻。","Wǒmen de lǎoshī hěn niánqīng.","Cô giáo của chúng mình rất trẻ."]],
"发现":["发: phát ra. 现 có bộ <b>王</b> (ngọc) + 见 (nhìn thấy): ngọc lộ ra trước mắt → hiện ra. Phát hiện, nhận ra.",["我发现他今天没来。","Wǒ fāxiàn tā jīntiān méi lái.","Mình phát hiện hôm nay anh ấy không đến."]],
"不见":["不 (không) + 见 (thấy, có 目 – con mắt ở trên): không thấy đâu → mất. Thường dùng 不见了.",["我的护照不见了。","Wǒ de hùzhào bú jiàn le.","Hộ chiếu của mình không thấy đâu nữa."]],
"带":["Phía dưới có bộ <b>巾</b> (cân – cái khăn): dải khăn, đai đeo bên người → mang theo, dẫn đi.",["我带你去吃饭。","Wǒ dài nǐ qù chī fàn.","Mình dẫn bạn đi ăn cơm."]],
"帮助":["帮 có bộ <b>巾</b> ở dưới. 助 có bộ <b>力</b> (lực – sức lực): góp sức → giúp. 帮助 mang tân ngữ được: 帮助他.",["谢谢你帮助我。","Xièxie nǐ bāngzhù wǒ.","Cảm ơn bạn đã giúp mình."]],
"照片":["照 có bộ <b>灬</b> (hỏa – ánh lửa) dưới: ánh sáng chiếu vào → chụp. 片: tấm mỏng. Tấm ảnh chụp.",["这是我家人的照片。","Zhè shì wǒ jiārén de zhàopiàn.","Đây là ảnh của gia đình mình."]]},
"3-2":{
"菜单":["菜 có bộ <b>艹</b> (thảo – cỏ, rau) → rau, món ăn. 单: tờ giấy, danh sách. Danh sách món ăn = thực đơn.",["服务员，请给我菜单。","Fúwùyuán, qǐng gěi wǒ càidān.","Em ơi, cho tôi xin thực đơn."]],
"又":["Hình bàn tay phải → làm đi làm lại → lại. 又……又……: vừa … vừa ….",["他又来了。","Tā yòu lái le.","Anh ấy lại đến rồi."]],
"饿":["Bộ <b>饣</b> (thực – ăn) + 我: “tôi” cần ăn → đói. Chữ có 饣 liên quan đến ăn uống: 饭, 饺, 馆.",["我饿了，我们去吃饭吧。","Wǒ è le, wǒmen qù chī fàn ba.","Mình đói rồi, mình đi ăn cơm đi."]],
"渴":["Bộ <b>氵</b> (thủy – nước) + 曷: cần nước → khát. Chữ có 氵 liên quan đến nước: 河, 洗. Còn 喝 (uống) có bộ 口.",["我很渴，想喝水。","Wǒ hěn kě, xiǎng hē shuǐ.","Mình khát lắm, muốn uống nước."]],
"客气":["客: người đến dưới mái nhà <b>宀</b> → khách. 气: hơi, khí. Thái độ của khách → khách sáo. Hay dùng: 别客气, 不客气.",["别客气，多吃点儿。","Bié kèqi, duō chī diǎnr.","Đừng khách sáo, ăn nhiều vào."]],
"饮料":["饮 có bộ <b>饣</b> → uống. 料 có bộ <b>米</b> (gạo) + 斗 (cái đấu): nguyên liệu. Thứ để uống = đồ uống.",["你喝什么饮料？","Nǐ hē shénme yǐnliào?","Bạn uống đồ uống gì?"]],
"好久":["好 ở đây = rất. 久: lâu. 好久没 + V + 了: lâu lắm rồi không ….",["好久不见！","Hǎojiǔ bú jiàn!","Lâu lắm không gặp!"]],
"服务":["服: quần áo, phục tùng (bộ 月). 务 có bộ <b>力</b> (sức lực): bỏ sức ra làm. Phục vụ.",["这家饭馆的服务很好。","Zhè jiā fànguǎn de fúwù hěn hǎo.","Phục vụ của nhà hàng này rất tốt."]],
"员":["Chữ 口 ở trên + 贝 (vỏ sò, tiền) ở dưới: người làm việc ăn lương → thành viên, người. Đặt cuối từ: 服务员.",["她是这家饭馆的服务员。","Tā shì zhè jiā fànguǎn de fúwùyuán.","Cô ấy là nhân viên phục vụ của nhà hàng này."]],
"双":["Hai chữ 又 (bàn tay) đứng cạnh nhau → một đôi. Dùng cho vật đi theo cặp: 一双筷子.",["请再给我一双筷子。","Qǐng zài gěi wǒ yì shuāng kuàizi.","Cho tôi thêm một đôi đũa."]],
"筷子":["筷 có bộ <b>⺮</b> (trúc – tre) + 快 (nhanh): que tre gắp thức ăn nhanh → đũa.",["我会用筷子吃饭。","Wǒ huì yòng kuàizi chī fàn.","Mình biết ăn cơm bằng đũa."]],
"勺子":["勺: hình cái muôi có chấm thức ăn bên trong → thìa, muôi. Chỉ 3 nét.",["请给我一个勺子。","Qǐng gěi wǒ yí ge sháozi.","Cho tôi một cái thìa."]],
"碗":["Bộ <b>石</b> (thạch – đá) + 宛: bát ngày xưa làm bằng đá, sứ → cái bát.",["我吃了两碗饭。","Wǒ chīle liǎng wǎn fàn.","Mình ăn hai bát cơm."]],
"马上":["马: con ngựa. 上: lên. Vừa lên ngựa là đi ngay → lập tức, ngay.",["我马上就来。","Wǒ mǎshàng jiù lái.","Mình đến ngay đây."]],
"热情":["热 có bộ <b>灬</b> (lửa) → nóng. 情 có bộ <b>忄</b> (tâm) → tình cảm. Tình cảm nóng hổi → nhiệt tình.",["他对人很热情。","Tā duì rén hěn rèqíng.","Anh ấy rất nhiệt tình với mọi người."]],
"尝":["Phía trên giống 尚, phía dưới có <b>云</b>. Nếm thử món ăn. Hay lặp lại: 尝尝 (nếm thử).",["你尝尝这个菜。","Nǐ chángchang zhège cài.","Bạn nếm thử món này đi."]],
"记":["Bộ <b>讠</b> (lời nói) + 己 (bản thân): lời nói ghi vào bản thân → nhớ, ghi. 记住: nhớ kỹ.",["你记住我的电话号码了吗？","Nǐ jìzhù wǒ de diànhuà hàomǎ le ma?","Bạn nhớ số điện thoại của mình chưa?"]],
"用":["Hình cái thùng gỗ có đai → đồ dùng → dùng. Chú ý: 用 chỉ có 5 nét, nét dọc giữa xuyên qua.",["我可以用一下你的手机吗？","Wǒ kěyǐ yòng yíxià nǐ de shǒujī ma?","Mình dùng điện thoại của bạn một chút được không?"]],
"鸡":["又 + bộ <b>鸟</b> (điểu – chim): loài chim nuôi trong nhà → con gà. 鸡肉: thịt gà.",["我喜欢吃鸡肉。","Wǒ xǐhuan chī jīròu.","Mình thích ăn thịt gà."]],
"张":["Bộ <b>弓</b> (cung) + 长: kéo căng dây cung → mở ra, trải ra. Lượng từ cho vật phẳng mỏng: 一张纸, 一张照片.",["这张照片很好看。","Zhè zhāng zhàopiàn hěn hǎokàn.","Tấm ảnh này rất đẹp."]],
"不用":["不 (không) + 用 (dùng, cần): không cần. Đọc biến điệu <b>bú</b>yòng.",["不用谢！","Búyòng xiè!","Không cần cảm ơn!"]],
"选":["Bộ <b>辶</b> (sước – bước đi) + 先 (trước): đi trước để chọn → chọn, lựa.",["你选一个吧。","Nǐ xuǎn yí ge ba.","Bạn chọn một cái đi."]],
"外卖":["外: bên ngoài. 卖: bán (có 十 ở trên, khác 买 mua). Bán mang ra ngoài → đồ ăn giao tận nơi.",["我们今天点外卖吧。","Wǒmen jīntiān diǎn wàimài ba.","Hôm nay mình đặt đồ ăn giao tận nơi đi."]],
"方便":["方: phương, hướng. 便 có bộ <b>亻</b> (người): điều thuận cho người → tiện. 便 trong 便宜 đọc pián.",["这里买东西很方便。","Zhèlǐ mǎi dōngxi hěn fāngbiàn.","Ở đây mua đồ rất tiện."]],
"蛋糕":["蛋: quả trứng (có bộ 虫 ở dưới). 糕 có bộ <b>米</b> (gạo, bột) + 羔: bánh làm từ bột → bánh ngọt.",["生日快乐！我们吃蛋糕吧。","Shēngrì kuàilè! Wǒmen chī dàngāo ba.","Chúc mừng sinh nhật! Mình ăn bánh kem nào."]],
"只":["口 ở trên + hai nét ở dưới. Phó từ đọc <b>zhǐ</b> = chỉ; lượng từ đọc <b>zhī</b> (一只猫).",["我只喝了一杯咖啡。","Wǒ zhǐ hēle yì bēi kāfēi.","Mình chỉ uống một cốc cà phê."]],
"方便面":["方便 (tiện) + 面 (mì): loại mì tiện lợi → mì ăn liền.",["方便面不能天天吃。","Fāngbiànmiàn bù néng tiāntiān chī.","Mì ăn liền không thể ngày nào cũng ăn."]],
"简单":["简 có bộ <b>⺮</b> (tre): thẻ tre ngày xưa viết chữ ngắn gọn → giản lược. 单: đơn. Đơn giản.",["这个问题很简单。","Zhège wèntí hěn jiǎndān.","Câu hỏi này rất đơn giản."]]},
"3-3":{
"初中":["初 có bộ <b>衤</b> (y – áo) + 刀 (dao): dùng dao cắt vải là bước đầu may áo → ban đầu. 中: giữa. Trường trung học bậc đầu = cấp hai.",["我妹妹在上初中。","Wǒ mèimei zài shàng chūzhōng.","Em gái mình đang học cấp hai."]],
"咱们":["咱 có bộ <b>口</b> (miệng) + 自 (bản thân): “chúng ta” gồm cả người đang nghe. 们 có bộ <b>亻</b>: số nhiều của người.",["咱们一起去吃饭吧。","Zánmen yìqǐ qù chī fàn ba.","Chúng ta cùng đi ăn cơm đi."]],
"换":["Bộ <b>扌</b> (tay) + 奂: tay đưa ra đổi lấy cái khác → thay, đổi.",["我想换一件衣服。","Wǒ xiǎng huàn yí jiàn yīfu.","Mình muốn đổi một cái áo khác."]],
"房子":["房 có bộ <b>户</b> (hộ – cánh cửa) + 方: nơi có cửa → nhà, phòng. 子 đọc nhẹ “zi”.",["他们家的房子很大。","Tāmen jiā de fángzi hěn dà.","Nhà của họ rất to."]],
"小区":["小: nhỏ. 区: khu vực (khung 匚 bao lấy chữ 㐅). Khu vực nhỏ có nhiều nhà ở = khu dân cư.",["我们小区有一个大超市。","Wǒmen xiǎoqū yǒu yí ge dà chāoshì.","Khu nhà mình có một siêu thị lớn."]],
"环境":["环 có bộ <b>王</b> (ngọc) → vòng ngọc, bao quanh. 境 có bộ <b>土</b> (đất) → vùng đất. Những gì bao quanh ta = môi trường.",["这里的环境很好。","Zhèlǐ de huánjìng hěn hǎo.","Môi trường ở đây rất tốt."]],
"挺":["Bộ <b>扌</b> (tay) + 廷: tay giữ thẳng → thẳng, cứng; khẩu ngữ mượn nghĩa “khá”. Hay dùng: 挺……的.",["这个菜挺好吃的。","Zhège cài tǐng hǎochī de.","Món này khá ngon."]],
"空调":["空: trống, không khí (có bộ 穴 – hang). 调 có bộ <b>讠</b> → điều chỉnh. Máy điều chỉnh không khí = điều hòa.",["天太热了，开空调吧。","Tiān tài rè le, kāi kōngtiáo ba.","Trời nóng quá, bật điều hòa đi."]],
"洗衣机":["洗 có bộ <b>氵</b> (nước) → giặt, rửa. 衣: áo. 机 có bộ <b>木</b> → máy. Máy giặt quần áo.",["我家的洗衣机是新的。","Wǒ jiā de xǐyījī shì xīn de.","Máy giặt nhà mình là đồ mới."]],
"层":["Bộ <b>尸</b> (thi – mái che) + 云: các tầng chồng lên nhau dưới mái → tầng.",["我家住在五层。","Wǒ jiā zhù zài wǔ céng.","Nhà mình ở tầng năm."]],
"花园":["花 có bộ <b>艹</b> (cỏ) + 化 → hoa. 园: khung 囗 bao quanh → khu vườn có rào. Vườn hoa.",["我们家有一个小花园。","Wǒmen jiā yǒu yí ge xiǎo huāyuán.","Nhà mình có một khu vườn nhỏ."]],
"灯":["Bộ <b>火</b> (lửa) + 丁: ngọn lửa thắp sáng → đèn.",["请开一下灯。","Qǐng kāi yíxià dēng.","Bật đèn giúp mình với."]],
"关":["Hình hai cánh cửa cài then lại → đóng, tắt. Trái nghĩa với 开 (mở, bật).",["出门的时候别忘了关灯。","Chū mén de shíhou bié wàngle guān dēng.","Lúc ra ngoài đừng quên tắt đèn."]],
"冰箱":["冰 có bộ <b>冫</b> (băng – nước đá) + 水 → băng, lạnh. 箱 có bộ <b>⺮</b> → hòm. Hòm lạnh = tủ lạnh.",["冰箱里有水果。","Bīngxiāng li yǒu shuǐguǒ.","Trong tủ lạnh có hoa quả."]],
"卫生间":["卫: bảo vệ. 生: sống. 卫生: vệ sinh. 间: căn phòng (日 trong 门). Phòng vệ sinh.",["请问，卫生间在哪儿？","Qǐngwèn, wèishēngjiān zài nǎr?","Xin hỏi, nhà vệ sinh ở đâu?"]],
"打扫":["打 có bộ <b>扌</b>. 扫 có bộ <b>扌</b> + 彐 (cái chổi): tay cầm chổi quét → quét dọn.",["今天我们打扫房间吧。","Jīntiān wǒmen dǎsǎo fángjiān ba.","Hôm nay mình dọn phòng đi."]],
"搬家":["搬 có bộ <b>扌</b> + 般: dùng tay bê vác. 家: nhà (lợn 豕 dưới mái 宀). Bê đồ chuyển nhà.",["我们下个月搬家。","Wǒmen xià ge yuè bānjiā.","Tháng sau nhà mình chuyển nhà."]],
"办":["力 (sức lực) ở giữa, hai chấm hai bên: bỏ sức ra làm → làm, xử lý (giấy tờ, thẻ).",["这件事我来办。","Zhè jiàn shì wǒ lái bàn.","Việc này để mình làm."]],
"信用卡":["信: người 亻 + lời 言 → tin. 用: dùng. 卡: trên 上 dưới 下 → tấm thẻ kẹp giữa. Thẻ dùng chữ tín = thẻ tín dụng.",["这里可以用信用卡吗？","Zhèlǐ kěyǐ yòng xìnyòngkǎ ma?","Ở đây dùng thẻ tín dụng được không?"]],
"还":["Chữ đa âm: <b>huán</b> = trả lại; <b>hái</b> = còn, vẫn. Bộ <b>辶</b> (bước đi): đi trở về → trả lại.",["明天我还你钱。","Míngtiān wǒ huán nǐ qián.","Mai mình trả tiền cho bạn."]],
"听说":["听 có bộ <b>口</b> → nghe. 说 có bộ <b>讠</b> → nói. Nghe người khác nói = nghe nói.",["听说他要去中国了。","Tīngshuō tā yào qù Zhōngguó le.","Nghe nói anh ấy sắp đi Trung Quốc."]],
"银行":["银 có bộ <b>钅</b> (kim loại) → bạc, tiền. 行 đọc <b>háng</b> (hàng, cửa hàng). Nơi giữ tiền = ngân hàng.",["银行几点开门？","Yínháng jǐ diǎn kāi mén?","Ngân hàng mấy giờ mở cửa?"]],
"才":["Chỉ 3 nét, giống chữ 寸 nhưng nét phẩy xuyên qua. Phó từ: (mãi) … mới.",["他十点才来。","Tā shí diǎn cái lái.","Mười giờ anh ấy mới đến."]],
"纸":["Bộ <b>纟</b> (mịch – sợi tơ) + 氏: giấy ngày xưa làm từ sợi → giấy.",["请给我一张纸。","Qǐng gěi wǒ yì zhāng zhǐ.","Cho mình một tờ giấy."]],
"搬":["Bộ <b>扌</b> (tay) + 般: dùng tay bê, chuyển đồ nặng.",["这个箱子太重了，我们一起搬吧。","Zhège xiāngzi tài zhòng le, wǒmen yìqǐ bān ba.","Thùng này nặng quá, mình cùng bê đi."]],
"需要":["需: mưa 雨 ở trên, cần chờ mưa → cần. 要: muốn, cần. 需要: cần thiết.",["你需要帮忙吗？","Nǐ xūyào bāngmáng ma?","Bạn có cần giúp không?"]]},
"3-4":{
"假期":["假 có bộ <b>亻</b>, đọc <b>jià</b> = ngày nghỉ (đọc jiǎ = giả). 期: kỳ, thời hạn (có 月). Kỳ nghỉ.",["假期你想去哪儿？","Jiàqī nǐ xiǎng qù nǎr?","Kỳ nghỉ bạn muốn đi đâu?"]],
"海":["Bộ <b>氵</b> (nước) + 每: nơi nước ở khắp mọi nơi → biển.",["我很喜欢看海。","Wǒ hěn xǐhuan kàn hǎi.","Mình rất thích ngắm biển."]],
"草原":["草 có bộ <b>艹</b> (cỏ). 原: cánh đồng rộng (厂 – sườn núi + 泉 nguồn nước). Đồng cỏ rộng = thảo nguyên.",["草原上有很多马。","Cǎoyuán shang yǒu hěn duō mǎ.","Trên thảo nguyên có nhiều ngựa."]],
"主意":["主: chủ (ngọn đèn có chấm lửa). 意 có bộ <b>心</b>: ý nghĩ trong lòng. 意 đọc nhẹ “yi”. Ý chủ đạo = ý kiến, ý tưởng.",["这是个好主意！","Zhè shì ge hǎo zhǔyi!","Đây là ý hay đấy!"]],
"骑":["Bộ <b>马</b> (ngựa) + 奇: ngồi trên lưng ngựa → cưỡi. Dùng cả cho xe đạp, xe máy.",["我会骑马。","Wǒ huì qí mǎ.","Mình biết cưỡi ngựa."]],
"马":["Hình con ngựa: đầu, bờm, bốn chân (nét ngang dưới). Chữ có 马 gợi âm “ma”: 妈, 吗, 码.",["我想去草原骑马。","Wǒ xiǎng qù cǎoyuán qí mǎ.","Mình muốn đi thảo nguyên cưỡi ngựa."]],
"羊":["Hình đầu con cừu có hai sừng (hai chấm trên), các nét ngang là thân. 羊肉: thịt cừu.",["草原上有很多羊。","Cǎoyuán shang yǒu hěn duō yáng.","Trên thảo nguyên có nhiều cừu."]],
"月亮":["月: hình mặt trăng khuyết. 亮: sáng (có 几 ở dưới, 亠 ở trên). Mặt trăng sáng. 亮 đọc nhẹ “liang”.",["今天的月亮很大。","Jīntiān de yuèliang hěn dà.","Trăng hôm nay rất to."]],
"一定":["一 + 定 (bộ <b>宀</b> – mái nhà: yên ổn, cố định). Đã cố định một rồi → nhất định, chắc chắn.",["我一定来。","Wǒ yídìng lái.","Mình nhất định sẽ đến."]],
"刻":["Bộ <b>刂</b> (đao – dao) + 亥: dùng dao khắc vạch → khắc. Một khắc = 15 phút.",["现在八点一刻。","Xiànzài bā diǎn yí kè.","Bây giờ là 8 giờ 15."]],
"起飞":["起 có bộ <b>走</b> (đi) → đứng dậy, bắt đầu. 飞: hình đôi cánh → bay. Bắt đầu bay = cất cánh.",["飞机几点起飞？","Fēijī jǐ diǎn qǐfēi?","Máy bay mấy giờ cất cánh?"]],
"宾馆":["宾 có bộ <b>宀</b> (mái nhà) → khách quý. 馆 có bộ <b>饣</b> (ăn) → quán, nơi ăn ở. Nơi khách ăn ở = khách sạn.",["这家宾馆很干净。","Zhè jiā bīnguǎn hěn gānjìng.","Khách sạn này rất sạch."]],
"特别":["特 có bộ <b>牛</b> (bò): con bò đực nổi bật → đặc biệt. 别 có bộ <b>刂</b> (dao): chia tách → khác. Khác hẳn = đặc biệt.",["这个地方特别漂亮。","Zhège dìfang tèbié piàoliang.","Nơi này đặc biệt đẹp."]],
"别的":["别 có bộ <b>刂</b> (dao) → tách riêng, khác. 的: của. 别的 = cái khác, người khác.",["你还要别的吗？","Nǐ hái yào biéde ma?","Bạn còn cần gì khác không?"]],
"一样":["一 + 样 (bộ <b>木</b> + 羊: khuôn gỗ, kiểu dáng). Cùng một kiểu = giống nhau.",["我们的衣服一样。","Wǒmen de yīfu yíyàng.","Áo của chúng mình giống nhau."]],
"牛":["Hình đầu con bò nhìn chính diện, nét dọc xuyên lên trên (khác 午 không xuyên). 牛肉: thịt bò.",["我喜欢吃牛肉。","Wǒ xǐhuan chī niúròu.","Mình thích ăn thịt bò."]],
"相机":["相 = 木 (cây) + 目 (mắt): mắt nhìn cây → nhìn, hình ảnh. 机 có bộ <b>木</b> → máy. Máy ghi hình = máy ảnh.",["这是我新买的相机。","Zhè shì wǒ xīn mǎi de xiàngjī.","Đây là máy ảnh mới mua của mình."]],
"欢迎":["欢 có 欠 (há miệng) → vui mừng. 迎 có bộ <b>辶</b> (bước đi) → đi ra đón. Vui mừng ra đón = hoan nghênh.",["欢迎你来我家！","Huānyíng nǐ lái wǒ jiā!","Chào mừng bạn đến nhà mình!"]],
"司机":["司: người làm việc, quản lý (có 口). 机: máy (bộ <b>木</b>). Người điều khiển máy = tài xế.",["他是出租车司机。","Tā shì chūzūchē sījī.","Anh ấy là tài xế taxi."]],
"晚点":["晚 có bộ <b>日</b> (mặt trời) → muộn, tối. 点: giờ. Muộn giờ = trễ, hoãn (xe, máy bay).",["火车晚点了。","Huǒchē wǎndiǎn le.","Tàu hỏa bị trễ rồi."]],
"久":["Chỉ 3 nét: hình người bị kéo lại phía sau, đi mãi không tới → lâu.",["好久不见！","Hǎojiǔ bú jiàn!","Lâu lắm không gặp!"]],
"除了":["除 có bộ <b>阝</b> (phụ – gò đất, ở bên trái) + 余: bỏ bớt đi → trừ ra. 了 đọc nhẹ “le”.",["除了他，我们都去。","Chúle tā, wǒmen dōu qù.","Trừ anh ấy ra, chúng mình đều đi."]],
"以外":["以: lấy, dùng. 外: bên ngoài (夕 + 卜). Ở phía ngoài = ngoài … ra. Hay đi với 除了.",["除了中文以外，我还会说英语。","Chúle Zhōngwén yǐwài, wǒ hái huì shuō Yīngyǔ.","Ngoài tiếng Trung, mình còn biết nói tiếng Anh."]],
"先":["Phía dưới là 儿 (đôi chân), phía trên là dấu chân đi trước → trước, trước tiên.",["你先走吧。","Nǐ xiān zǒu ba.","Bạn đi trước đi."]],
"一直":["一 + 直 (có 目 – con mắt: nhìn thẳng) → thẳng. Một mạch thẳng = luôn luôn, suốt.",["我一直在等你。","Wǒ yìzhí zài děng nǐ.","Mình vẫn luôn đợi bạn."]],
"干净":["干: khô (đọc gān). 净 có bộ <b>冫</b> (nước đá, trong) → sạch. Khô ráo, sạch sẽ.",["房间很干净。","Fángjiān hěn gānjìng.","Căn phòng rất sạch."]],
"满意":["满 có bộ <b>氵</b> (nước) → đầy. 意 có bộ <b>心</b> → ý, lòng. Lòng đầy đủ = hài lòng.",["我对这个房间很满意。","Wǒ duì zhège fángjiān hěn mǎnyì.","Mình rất hài lòng với căn phòng này."]]},
"3-5":{
"总是":["总: tổng, gom lại (có bộ <b>心</b> ở dưới). 是: là. Lần nào gom lại cũng là → luôn luôn.",["他总是很忙。","Tā zǒngshì hěn máng.","Anh ấy lúc nào cũng bận."]],
"终于":["终 có bộ <b>纟</b> (sợi tơ) + 冬 (mùa đông, cuối năm): đầu cuối sợi tơ → kết thúc. 于: ở. Cuối cùng.",["他终于来了。","Tā zhōngyú lái le.","Cuối cùng anh ấy cũng đến."]],
"爬":["Bộ <b>爪</b> (trảo – móng vuốt) + 巴: dùng tay chân bám mà leo → leo, bò.",["我们去爬山吧。","Wǒmen qù pá shān ba.","Mình đi leo núi đi."]],
"山":["Hình ba ngọn núi, ngọn giữa cao nhất. Chỉ 3 nét.",["那里的山很高。","Nàlǐ de shān hěn gāo.","Núi ở đó rất cao."]],
"锻炼":["锻 có bộ <b>钅</b> (kim loại) → rèn sắt. 炼 có bộ <b>火</b> (lửa) → luyện. Rèn luyện kim loại → rèn luyện thân thể.",["我每天早上锻炼身体。","Wǒ měi tiān zǎoshang duànliàn shēntǐ.","Mỗi sáng mình tập thể dục."]],
"照":["Bộ <b>灬</b> (hỏa – lửa) ở dưới + 昭: ánh sáng chiếu → chiếu, chụp (ảnh).",["我给你照一张吧。","Wǒ gěi nǐ zhào yì zhāng ba.","Mình chụp cho bạn một tấm nhé."]],
"鞋":["Bộ <b>革</b> (cách – da thuộc) + 圭: đồ làm bằng da để đi → giày.",["这双鞋很舒服。","Zhè shuāng xié hěn shūfu.","Đôi giày này rất êm."]],
"大衣":["大: to. 衣: áo (hình cổ áo và vạt áo). Áo to mặc ngoài = áo khoác.",["天冷了，穿上大衣吧。","Tiān lěng le, chuānshang dàyī ba.","Trời lạnh rồi, mặc áo khoác vào đi."]],
"拍照":["拍 có bộ <b>扌</b> (tay) + 白: vỗ, bấm. 照 có bộ <b>灬</b> → chụp. Bấm máy chụp ảnh.",["我们在这儿拍照吧。","Wǒmen zài zhèr pāizhào ba.","Mình chụp ảnh ở đây đi."]],
"感兴趣":["感 có bộ <b>心</b> → cảm thấy. 兴 đọc <b>xìng</b>: hứng. 趣 có bộ <b>走</b> → thú vị. Cấu trúc: 对 + việc + 感兴趣.",["我对中国音乐很感兴趣。","Wǒ duì Zhōngguó yīnyuè hěn gǎn xìngqù.","Mình rất hứng thú với âm nhạc Trung Quốc."]],
"照相":["照 (chụp, bộ <b>灬</b>) + 相 (hình ảnh, 木 + 目). Chụp ảnh. 照相 = 拍照.",["他经常给我照相。","Tā jīngcháng gěi wǒ zhàoxiàng.","Anh ấy hay chụp ảnh cho mình."]],
"难看":["难: khó (có 隹 – chim đuôi ngắn). 看: nhìn (tay 手 che trên mắt 目). Khó nhìn = xấu.",["这件衣服有点儿难看。","Zhè jiàn yīfu yǒudiǎnr nánkàn.","Cái áo này hơi xấu."]],
"比较":["比: hai người đứng cạnh nhau → so. 较 có bộ <b>车</b> (xe) + 交: so sánh. Phó từ: tương đối.",["今天比较冷。","Jīntiān bǐjiào lěng.","Hôm nay tương đối lạnh."]],
"水平":["水: nước. 平: phẳng. Mặt nước phẳng dùng làm chuẩn đo → mức, trình độ.",["他的中文水平很高。","Tā de Zhōngwén shuǐpíng hěn gāo.","Trình độ tiếng Trung của anh ấy rất cao."]],
"太阳":["太: rất (大 thêm chấm). 阳 có bộ <b>阝</b> + 日 (mặt trời) → dương, ánh nắng. Mặt trời.",["今天太阳很大。","Jīntiān tàiyáng hěn dà.","Hôm nay nắng to."]],
"树":["Bộ <b>木</b> (mộc – cây) + 对: cây đứng thẳng → cái cây.",["我家前面有很多树。","Wǒ jiā qiánmiàn yǒu hěn duō shù.","Trước nhà mình có nhiều cây."]],
"干":["Đọc <b>gàn</b> = làm (khẩu ngữ); đọc <b>gān</b> = khô (干净). Chỉ 3 nét, nét dọc không xuyên lên trên (khác 千).",["你在干什么？","Nǐ zài gàn shénme?","Bạn đang làm gì thế?"]],
"电":["Hình tia chớp xuyên qua đám mây (日) → điện. 电话, 电视, 电脑 đều có chữ này.",["手机没电了。","Shǒujī méi diàn le.","Điện thoại hết pin rồi."]],
"收到":["收 có 攵 (tay cầm gậy) → thu, nhận. 到 có bộ <b>刂</b> → đến. Nhận được.",["你收到我的邮件了吗？","Nǐ shōudào wǒ de yóujiàn le ma?","Bạn nhận được email của mình chưa?"]],
"封":["Bộ <b>寸</b> (tay) + 圭 (đất): dùng tay đắp đất niêm phong → phong, bức thư. Lượng từ cho thư.",["我给他写了一封信。","Wǒ gěi tā xiěle yì fēng xìn.","Mình viết cho anh ấy một bức thư."]],
"邮件":["邮 có bộ <b>阝</b> (thành ấp) → bưu, thư. 件 có bộ <b>亻</b> + 牛 → món, cái. Thư từ = email.",["我每天早上看邮件。","Wǒ měi tiān zǎoshang kàn yóujiàn.","Sáng nào mình cũng xem email."]],
"难过":["难: khó. 过 có bộ <b>辶</b> → trải qua. Khó trải qua = buồn.",["别难过了。","Bié nánguò le.","Đừng buồn nữa."]],
"哈哈":["Bộ <b>口</b> (miệng) + 合: tiếng phát ra từ miệng → tiếng cười ha ha.",["哈哈，你说得太对了！","Hāhā, nǐ shuō de tài duì le!","Ha ha, bạn nói đúng quá!"]],
"音乐":["音: âm thanh (立 + 日). 乐 đọc <b>yuè</b> = nhạc (đọc lè = vui). Âm nhạc.",["我喜欢听音乐。","Wǒ xǐhuan tīng yīnyuè.","Mình thích nghe nhạc."]],
"兴趣":["兴 đọc <b>xìng</b>: hứng. 趣 có bộ <b>走</b> + 取 → thú vị. Hứng thú (danh từ): 有兴趣.",["你对什么有兴趣？","Nǐ duì shénme yǒu xìngqù?","Bạn có hứng thú với cái gì?"]],
"会":["Chữ đa nghĩa: động từ năng nguyện “biết, sẽ”; danh từ “buổi họp, buổi gặp mặt” (音乐会 buổi hòa nhạc).",["今天下午有一个会。","Jīntiān xiàwǔ yǒu yí ge huì.","Chiều nay có một cuộc họp."]],
"结束":["结 có bộ <b>纟</b> (sợi tơ) → buộc, kết. 束: bó (cây 木 bị buộc). Buộc lại = kết thúc.",["电影几点结束？","Diànyǐng jǐ diǎn jiéshù?","Phim mấy giờ kết thúc?"]]},
"3-6":{
"该":["Bộ <b>讠</b> (lời nói) + 亥: lời nói phải làm → nên, phải. 该……了: đến lúc phải ….",["该吃饭了。","Gāi chī fàn le.","Đến giờ ăn cơm rồi."]],
"打算":["打: đánh (bộ <b>扌</b>). 算 có bộ <b>⺮</b> (tre – que tính) + 目: tính toán. Tính trước = dự định.",["你明天打算做什么？","Nǐ míngtiān dǎsuàn zuò shénme?","Mai bạn định làm gì?"]],
"高铁":["高: cao. 铁 có bộ <b>钅</b> (kim loại) → sắt, đường sắt. 高速铁路 nói gọn = tàu cao tốc.",["我坐高铁去上海。","Wǒ zuò gāotiě qù Shànghǎi.","Mình đi tàu cao tốc đến Thượng Hải."]],
"行":["Hình ngã tư đường → đi. Đọc <b>xíng</b>: được, ổn (行！); đọc <b>háng</b>: hàng (银行).",["明天去？行！","Míngtiān qù? Xíng!","Mai đi à? Được!"]],
"路口":["路 có bộ <b>足</b> (chân) → đường. 口: miệng, cửa. Chỗ “miệng” đường gặp nhau = giao lộ.",["前面的路口往右走。","Qiánmiàn de lùkǒu wǎng yòu zǒu.","Đến giao lộ phía trước rẽ phải."]],
"小心":["小: nhỏ. 心: tim, lòng. Để lòng thật nhỏ, thật kỹ → cẩn thận.",["路上小心！","Lùshang xiǎoxīn!","Đi đường cẩn thận nhé!"]],
"迟到":["迟 có bộ <b>辶</b> (bước đi) → chậm. 到: đến. Đến chậm = đến muộn.",["对不起，我迟到了。","Duìbuqǐ, wǒ chídào le.","Xin lỗi, mình đến muộn."]],
"红绿灯":["红 (đỏ) + 绿 (xanh, bộ <b>纟</b>) + 灯 (đèn, bộ <b>火</b>). Đèn đỏ đèn xanh = đèn giao thông.",["前面有红绿灯，慢一点儿。","Qiánmiàn yǒu hónglǜdēng, màn yìdiǎnr.","Phía trước có đèn giao thông, chậm lại chút."]],
"后来":["后: sau. 来: đến. Sau đó, về sau (nói về chuyện đã qua).",["后来他去了中国。","Hòulái tā qùle Zhōngguó.","Về sau anh ấy đi Trung Quốc."]],
"急":["Phía dưới có bộ <b>心</b> (tim): trong lòng gấp gáp → vội, lo, cuống.",["别急，慢慢说。","Bié jí, mànmàn shuō.","Đừng vội, nói từ từ."]],
"如果":["如 có bộ <b>女</b> + 口: như, nếu. 果: quả (cây có trái) → kết quả. Nếu … thì có kết quả.",["如果下雨，我们就不去了。","Rúguǒ xià yǔ, wǒmen jiù bú qù le.","Nếu mưa thì chúng mình không đi nữa."]],
"以前":["以: lấy (làm mốc). 前: trước. Trước đây.",["我以前不会说中文。","Wǒ yǐqián bú huì shuō Zhōngwén.","Trước đây mình không biết nói tiếng Trung."]],
"耳机":["耳: hình cái tai. 机: máy (bộ <b>木</b>). Máy đeo ở tai = tai nghe.",["我在用耳机听音乐。","Wǒ zài yòng ěrjī tīng yīnyuè.","Mình đang dùng tai nghe nghe nhạc."]],
"充电宝":["充: nạp đầy. 电: điện. 宝 có bộ <b>宀</b> + 玉 (ngọc) → báu vật. “Báu vật nạp điện” = sạc dự phòng.",["你有充电宝吗？","Nǐ yǒu chōngdiànbǎo ma?","Bạn có sạc dự phòng không?"]],
"常用":["常: thường (có 巾 ở dưới). 用: dùng. Thường dùng.",["这是我常用的手机。","Zhè shì wǒ cháng yòng de shǒujī.","Đây là điện thoại mình hay dùng."]],
"越":["Bộ <b>走</b> (đi) + 戉: vượt qua → càng. 越来越: ngày càng. 越南: Việt Nam.",["天气越来越冷了。","Tiānqì yuè lái yuè lěng le.","Trời ngày càng lạnh."]],
"分开":["分: dao 刀 chia đôi 八 → chia. 开: mở. Chia ra, tách ra.",["我们别分开走。","Wǒmen bié fēnkāi zǒu.","Chúng mình đừng đi tách nhau."]],
"检查":["检 có bộ <b>木</b> → kiểm. 查 có bộ <b>木</b> + 日 → tra xét. Kiểm tra.",["请检查一下你的行李。","Qǐng jiǎnchá yíxià nǐ de xíngli.","Mời kiểm tra lại hành lý của bạn."]],
"刷":["Bộ <b>刂</b> (dao) bên phải + 尸 巾: chà, quét qua → quét thẻ, chải.",["我可以刷卡吗？","Wǒ kěyǐ shuā kǎ ma?","Mình quẹt thẻ được không?"]],
"检票":["检: kiểm. 票: vé (示 ở dưới). Kiểm vé, soát vé.",["检票口在哪儿？","Jiǎnpiàokǒu zài nǎr?","Cửa soát vé ở đâu?"]],
"电梯":["电: điện. 梯 có bộ <b>木</b> + 弟: cái thang gỗ. Thang chạy bằng điện = thang máy.",["我们坐电梯上去吧。","Wǒmen zuò diàntī shàngqu ba.","Mình đi thang máy lên đi."]],
"放假":["放: thả ra (có 攵). 假 đọc <b>jià</b>: kỳ nghỉ. Được thả cho nghỉ = nghỉ lễ.",["学校下星期放假。","Xuéxiào xià xīngqī fàngjià.","Tuần sau trường được nghỉ."]],
"沙发":["Phiên âm từ “sofa”. 沙 có bộ <b>氵</b> (cát). 发: phát.",["他坐在沙发上看电视。","Tā zuò zài shāfā shang kàn diànshì.","Anh ấy ngồi trên sofa xem ti vi."]],
"安静":["安: người nữ 女 dưới mái nhà 宀 → yên ổn. 静 có 青 + 争: lặng. Yên tĩnh.",["图书馆里很安静。","Túshūguǎn li hěn ānjìng.","Trong thư viện rất yên tĩnh."]],
"选择":["选 có bộ <b>辶</b> → chọn. 择 có bộ <b>扌</b> (tay) → lựa. Chọn lựa.",["你选择哪一个？","Nǐ xuǎnzé nǎ yí ge?","Bạn chọn cái nào?"]],
"必须":["必: tất (trái tim 心 có nét phẩy xuyên qua) → nhất định. 须: cần (có 页). Nhất định phải.",["明天你必须来。","Míngtiān nǐ bìxū lái.","Mai bạn nhất định phải đến."]],
"北京南站":["北京: Bắc Kinh. 南: phía nam. 站: ga (bộ <b>立</b>). Ga Bắc Kinh Nam.",["我们在北京南站坐高铁。","Wǒmen zài Běijīng Nán Zhàn zuò gāotiě.","Chúng mình đi tàu cao tốc ở ga Bắc Kinh Nam."]]},
"3-7":{
"辆":["Bộ <b>车</b> (xe) + 两: lượng từ cho xe cộ. 一辆车, 一辆自行车.",["我家有两辆车。","Wǒ jiā yǒu liǎng liàng chē.","Nhà mình có hai chiếc xe."]],
"自行车":["自: tự. 行: đi. 车: xe. Xe tự đi (bằng sức mình) = xe đạp.",["我每天骑自行车去学校。","Wǒ měi tiān qí zìxíngchē qù xuéxiào.","Mỗi ngày mình đạp xe đi học."]],
"旧":["Bộ <b>丨</b> + 日 (mặt trời): đã qua nhiều ngày → cũ. Trái nghĩa với 新.",["这件衣服有点儿旧了。","Zhè jiàn yīfu yǒudiǎnr jiù le.","Cái áo này hơi cũ rồi."]],
"矮":["Bộ <b>矢</b> (mũi tên – vật ngắn) + 委: thấp, lùn. Trái nghĩa với 高.",["我比哥哥矮一点儿。","Wǒ bǐ gēge ǎi yìdiǎnr.","Mình thấp hơn anh trai một chút."]],
"试":["Bộ <b>讠</b> (lời nói) + 式 (kiểu): nói thử theo kiểu → thử. 考试: thi.",["这件衣服可以试一下吗？","Zhè jiàn yīfu kěyǐ shì yíxià ma?","Cái áo này mặc thử được không?"]],
"黄色":["黄: màu vàng của đất. 色: màu sắc. Màu vàng.",["我喜欢黄色。","Wǒ xǐhuan huángsè.","Mình thích màu vàng."]],
"短裤":["短: ngắn (bộ 矢). 裤 có bộ <b>衤</b> (áo quần) + 库: quần. Quần ngắn = quần soóc.",["夏天我常穿短裤。","Xiàtiān wǒ cháng chuān duǎnkù.","Mùa hè mình hay mặc quần soóc."]],
"大小":["大 (to) + 小 (nhỏ): to nhỏ = kích cỡ.",["这双鞋大小合适吗？","Zhè shuāng xié dàxiǎo héshì ma?","Đôi giày này cỡ vừa không?"]],
"合适":["合: hợp lại (人 + 一 + 口). 适 có bộ <b>辶</b> → vừa. Vừa vặn, phù hợp.",["这件衣服很合适。","Zhè jiàn yīfu hěn héshì.","Cái áo này rất vừa."]],
"裙子":["裙 có bộ <b>衤</b> (áo quần) + 君: váy. 子 đọc nhẹ “zi”.",["她穿了一条红裙子。","Tā chuānle yì tiáo hóng qúnzi.","Cô ấy mặc một chiếc váy đỏ."]],
"更":["Phó từ “càng, hơn”, đứng trước tính từ: 更好看. Chữ có 日 ở giữa, nét dưới kéo dài.",["今天比昨天更冷。","Jīntiān bǐ zuótiān gèng lěng.","Hôm nay lạnh hơn hôm qua."]],
"决定":["决 có bộ <b>冫</b> (nước): khơi dòng nước → quyết. 定: định (bộ 宀). Quyết định.",["我决定明天去北京。","Wǒ juédìng míngtiān qù Běijīng.","Mình quyết định mai đi Bắc Kinh."]],
"西瓜":["西: phía tây. 瓜: quả dưa (hình dây leo có quả). Dưa từ phương Tây = dưa hấu.",["夏天吃西瓜真舒服。","Xiàtiān chī xīguā zhēn shūfu.","Mùa hè ăn dưa hấu thật dễ chịu."]],
"新鲜":["新: mới. 鲜 có bộ <b>鱼</b> (cá) + 羊 (cừu): cá và thịt tươi → tươi. Tươi mới.",["这些水果很新鲜。","Zhèxiē shuǐguǒ hěn xīnxiān.","Hoa quả này rất tươi."]],
"甜":["Bộ <b>舌</b> (lưỡi) + 甘 (ngọt): lưỡi nếm thấy ngọt → ngọt.",["这个苹果很甜。","Zhège píngguǒ hěn tián.","Quả táo này rất ngọt."]],
"公斤":["公: chung, công. 斤: cân (hình cái rìu). Cân quốc tế = kilôgam (1 公斤 = 2 斤).",["我买了两公斤苹果。","Wǒ mǎile liǎng gōngjīn píngguǒ.","Mình mua hai cân (kg) táo."]],
"冰":["Bộ <b>冫</b> (băng) + 水 (nước): nước đóng băng → đá, lạnh.",["我想喝冰水。","Wǒ xiǎng hē bīng shuǐ.","Mình muốn uống nước đá."]],
"极":["Bộ <b>木</b> + 及: cây xà nhà cao nhất → cực, tột cùng. 极了: … cực kỳ.",["这里的西瓜好吃极了。","Zhèlǐ de xīguā hǎochī jí le.","Dưa hấu ở đây ngon cực kỳ."]],
"斤":["Hình cái rìu cổ dùng làm quả cân → cân (500 gam).",["一斤苹果多少钱？","Yì jīn píngguǒ duōshao qián?","Một cân táo bao nhiêu tiền?"]],
"香蕉":["香: thơm (禾 lúa + 日). 蕉 có bộ <b>艹</b> + 焦: cây chuối. Chuối thơm = chuối tiêu.",["我每天吃一个香蕉。","Wǒ měi tiān chī yí ge xiāngjiāo.","Mỗi ngày mình ăn một quả chuối."]],
"一共":["一: một. 共: chung (hai tay cầm chung). Gộp chung lại = tổng cộng.",["一共多少钱？","Yígòng duōshao qián?","Tổng cộng bao nhiêu tiền?"]],
"毛":["Hình sợi lông → lông. Mượn làm đơn vị tiền: 1 块 = 10 毛.",["这个五块五毛。","Zhège wǔ kuài wǔ máo.","Cái này năm tệ rưỡi."]],
"结婚":["结 có bộ <b>纟</b> → buộc, kết. 婚 có bộ <b>女</b> + 昏 (hoàng hôn: ngày xưa cưới lúc chiều tối). Kết hôn.",["他们去年结婚了。","Tāmen qùnián jiéhūn le.","Họ kết hôn năm ngoái."]],
"不但":["不: không. 但: chỉ (bộ <b>亻</b> + 旦). Không chỉ = không những. Đi với 而且.",["她不但会唱歌，而且会跳舞。","Tā búdàn huì chànggē, érqiě huì tiàowǔ.","Cô ấy không những biết hát mà còn biết nhảy."]],
"而且":["而: hình bộ râu → nối tiếp. 且: hơn nữa. Mà còn.",["这里的菜好吃，而且不贵。","Zhèlǐ de cài hǎochī, érqiě bú guì.","Món ăn ở đây ngon mà còn không đắt."]],
"声":["Phía trên 士, dưới 尸 có nét: âm thanh. Lượng từ: 叫一声 (gọi một tiếng).",["他叫了我一声。","Tā jiàole wǒ yì shēng.","Anh ấy gọi mình một tiếng."]],
"开机":["开: mở, bật. 机: máy. Bật máy (điện thoại, ti vi, máy tính).",["我的手机开不了机。","Wǒ de shǒujī kāi bu liǎo jī.","Điện thoại mình không bật lên được."]]},
"3-8":{
"最近":["最: nhất. 近 có bộ <b>辶</b> + 斤: gần. Gần nhất về thời gian = gần đây, dạo này.",["你最近忙吗？","Nǐ zuìjìn máng ma?","Dạo này bạn bận không?"]],
"常":["Phía dưới có bộ <b>巾</b> (khăn): khăn dùng hằng ngày → thường. 常常, 经常.",["我常去那家饭馆。","Wǒ cháng qù nà jiā fànguǎn.","Mình hay đến quán đó."]],
"体育馆":["体: thân thể (亻 + 本). 育: nuôi dưỡng. 馆: quán, nhà lớn. Nhà rèn luyện thân thể = nhà thi đấu.",["我们在体育馆打球。","Wǒmen zài tǐyùguǎn dǎ qiú.","Chúng mình chơi bóng ở nhà thi đấu."]],
"习惯":["习: tập (hình đôi cánh chim tập bay). 惯 có bộ <b>忄</b> (tâm) + 贯: quen trong lòng. Thói quen.",["我习惯早上喝咖啡。","Wǒ xíguàn zǎoshang hē kāfēi.","Mình quen uống cà phê buổi sáng."]],
"胖":["Bộ <b>月</b> (nhục – thịt) + 半: nhiều thịt → béo. Trái nghĩa với 瘦.",["他比以前胖了。","Tā bǐ yǐqián pàng le.","Anh ấy béo hơn trước."]],
"健康":["健 có bộ <b>亻</b> → khỏe. 康: an khang. Khỏe mạnh.",["祝你身体健康！","Zhù nǐ shēntǐ jiànkāng!","Chúc bạn sức khỏe!"]],
"以后":["以: lấy (làm mốc). 后: sau. Sau này, về sau.",["下课以后我们去吃饭。","Xiàkè yǐhòu wǒmen qù chī fàn.","Tan học xong mình đi ăn."]],
"羽毛球":["羽: hình đôi cánh lông vũ. 毛: lông. 球 có bộ <b>王</b> (ngọc) → quả cầu. Quả cầu lông vũ = cầu lông.",["我喜欢打羽毛球。","Wǒ xǐhuan dǎ yǔmáoqiú.","Mình thích chơi cầu lông."]],
"耳朵":["耳: hình cái tai. 朵: bông, đóa (木 + 几). 朵 đọc nhẹ “duo”.",["我的耳朵有点儿疼。","Wǒ de ěrduo yǒudiǎnr téng.","Tai mình hơi đau."]],
"感冒":["感: cảm (bộ <b>心</b>). 冒: bốc lên, nhiễm (日 trên 目). Nhiễm lạnh = bị cảm.",["我感冒了，不想吃饭。","Wǒ gǎnmào le, bù xiǎng chī fàn.","Mình bị cảm, không muốn ăn."]],
"发烧":["发: phát ra. 烧 có bộ <b>火</b> (lửa) → nóng, đốt. Người phát nóng = sốt.",["孩子发烧了。","Háizi fāshāo le.","Con bị sốt rồi."]],
"低":["Bộ <b>亻</b> (người) + 氐 (gốc, đáy): người cúi xuống → thấp. Trái nghĩa với 高.",["他发低烧了。","Tā fā dī shāo le.","Anh ấy bị sốt nhẹ."]],
"关心":["关: đóng, liên quan. 心: lòng. Để tâm đến người khác = quan tâm.",["谢谢你的关心。","Xièxie nǐ de guānxīn.","Cảm ơn sự quan tâm của bạn."]],
"注意":["注 có bộ <b>氵</b> (nước) + 主: rót vào. 意 có bộ <b>心</b>. Rót ý vào = chú ý.",["开车的时候要注意红绿灯。","Kāichē de shíhou yào zhùyì hónglǜdēng.","Lúc lái xe phải chú ý đèn giao thông."]],
"突然":["突: con chó 犬 lao ra khỏi hang 穴 → đột ngột. 然: như thế (có bộ <b>灬</b>).",["外面突然下雨了。","Wàimiàn tūrán xià yǔ le.","Bên ngoài đột nhiên mưa."]],
"住院":["住: ở (bộ <b>亻</b>). 院 có bộ <b>阝</b> → viện, sân. Ở lại bệnh viện = nằm viện.",["他住院一个星期了。","Tā zhùyuàn yí ge xīngqī le.","Anh ấy nằm viện một tuần rồi."]],
"担心":["担 có bộ <b>扌</b> (tay) → gánh. 心: lòng. Lòng gánh nặng = lo lắng.",["别担心，我没事。","Bié dānxīn, wǒ méi shì.","Đừng lo, mình không sao."]],
"腿":["Bộ <b>月</b> (thịt) + 退 (lui): phần cơ thể dùng để bước lui tới → chân, cẳng chân.",["我的腿很疼。","Wǒ de tuǐ hěn téng.","Chân mình rất đau."]],
"病人":["病 có bộ <b>疒</b> (bệnh) + 丙. 人: người. Người bệnh = bệnh nhân.",["医生在看病人。","Yīshēng zài kàn bìngrén.","Bác sĩ đang khám cho bệnh nhân."]],
"差不多":["差: kém (đọc chà). 不多: không nhiều. Kém không nhiều = xấp xỉ, gần như. 多 đọc nhẹ “duo”.",["我和哥哥差不多高。","Wǒ hé gēge chàbuduō gāo.","Mình và anh trai cao xấp xỉ nhau."]],
"得":["Chữ đa âm: <b>de</b> (跑得快), <b>dé</b> (được), <b>děi</b> = phải (khẩu ngữ). Bộ <b>彳</b> (bước chân).",["我得走了。","Wǒ děi zǒu le.","Mình phải đi rồi."]],
"开心":["开: mở. 心: lòng. Lòng mở ra = vui vẻ.",["今天我很开心。","Jīntiān wǒ hěn kāixīn.","Hôm nay mình rất vui."]],
"出院":["出: ra (núi chồng núi). 院: bệnh viện. Ra viện = xuất viện. Trái nghĩa 住院.",["他明天出院。","Tā míngtiān chūyuàn.","Mai anh ấy xuất viện."]],
"开":["Hình hai tay mở then cửa → mở. Nghĩa mới: kê (đơn thuốc): 开药.",["医生给我开了药。","Yīshēng gěi wǒ kāile yào.","Bác sĩ kê thuốc cho mình."]],
"种":["Bộ <b>禾</b> (lúa) + 中: hạt giống → giống, loại. Lượng từ đọc <b>zhǒng</b>.",["这种水果很好吃。","Zhè zhǒng shuǐguǒ hěn hǎochī.","Loại hoa quả này rất ngon."]],
"方法":["方: phương, cách. 法 có bộ <b>氵</b> (nước) + 去: luật lệ như nước chảy. Cách làm = phương pháp.",["你学中文的方法很好。","Nǐ xué Zhōngwén de fāngfǎ hěn hǎo.","Phương pháp học tiếng Trung của bạn rất tốt."]],
"其他":["其: cái đó. 他: khác, người khác (bộ <b>亻</b>). Cái khác, người khác.",["其他人都走了。","Qítā rén dōu zǒu le.","Những người khác đều đi rồi."]],
"心里":["心: tim, lòng. 里: bên trong. Trong lòng. 里 đọc nhẹ “li”.",["我心里很高兴。","Wǒ xīnli hěn gāoxìng.","Trong lòng mình rất vui."]]},
"3-9":{
"校园":["校 có bộ <b>木</b> (cây): trường học. 园 có bộ <b>囗</b> (vây quanh): vườn. Khu vườn của trường = khuôn viên trường.",["我们的校园很大。","Wǒmen de xiàoyuán hěn dà.","Khuôn viên trường mình rất rộng."]],
"卡":["Trên 上, dưới 下: kẹt ở giữa → cái thẻ kẹp được. Đọc <b>kǎ</b>: 校园卡, 银行卡.",["我的校园卡找不到了。","Wǒ de xiàoyuánkǎ zhǎo bu dào le.","Thẻ sinh viên của mình không tìm thấy nữa."]],
"球场":["球 có bộ <b>王</b> (ngọc) + 求: quả bóng. 场 có bộ <b>土</b> (đất): bãi, sân. Sân bóng.",["他们下课以后常去球场。","Tāmen xiàkè yǐhòu cháng qù qiúchǎng.","Tan học họ hay ra sân bóng."]],
"为了":["为 đọc <b>wèi</b> = vì. 了 đọc <b>le</b>. 为了 + mục đích: để. Đừng nhầm với 因为 (vì, nguyên nhân).",["为了身体健康，我每天跑步。","Wèile shēntǐ jiànkāng, wǒ měi tiān pǎobù.","Để cơ thể khỏe mạnh, ngày nào mình cũng chạy bộ."]],
"运动会":["运动: vận động, thể thao. 会: hội. Đại hội thể dục thể thao.",["学校下个月开运动会。","Xuéxiào xià ge yuè kāi yùndònghuì.","Tháng sau trường tổ chức đại hội thể thao."]],
"男生":["男: <b>田</b> (ruộng) + <b>力</b> (sức) → người làm ruộng bằng sức = nam. 生: học sinh. Nam sinh.",["我们班男生比女生多。","Wǒmen bān nánshēng bǐ nǚshēng duō.","Lớp mình nam nhiều hơn nữ."]],
"练":["Bộ <b>纟</b> (tơ) + 东 biến thể: luyện tơ cho mềm → luyện, tập. 练球, 练字.",["他每天下午都去练球。","Tā měi tiān xiàwǔ dōu qù liàn qiú.","Chiều nào anh ấy cũng đi tập bóng."]],
"参加":["参 (cān): tham dự. 加 = <b>力</b> + <b>口</b>: thêm vào. Tham gia.",["你参加这次比赛吗？","Nǐ cānjiā zhè cì bǐsài ma?","Bạn có tham gia cuộc thi lần này không?"]],
"网球":["网 có hình cái lưới. 球: bóng. Bóng đánh qua lưới = quần vợt.",["我想学打网球。","Wǒ xiǎng xué dǎ wǎngqiú.","Mình muốn học chơi quần vợt."]],
"比赛":["比: hai người đứng cạnh so bì. 赛 có bộ <b>贝</b> (tiền thưởng). So tài lấy thưởng = thi đấu.",["今天晚上有足球比赛。","Jīntiān wǎnshang yǒu zúqiú bǐsài.","Tối nay có trận bóng đá."]],
"练习":["练: luyện. 习 hình chim non tập bay. Luyện tập; cũng là danh từ: bài tập.",["这个练习不太难。","Zhège liànxí bú tài nán.","Bài tập này không khó lắm."]],
"好多":["好: rất (nhấn mạnh). 多: nhiều. 好多 = khá nhiều, rất nhiều (khẩu ngữ).",["我好多年没回老家了。","Wǒ hǎoduō nián méi huí lǎojiā le.","Nhiều năm rồi mình chưa về quê."]],
"几乎":["几: gần. 乎: trợ từ. Gần như, hầu như. Hay đi với 都 / 没.",["他几乎每天都来。","Tā jīhū měi tiān dōu lái.","Anh ấy hầu như ngày nào cũng đến."]],
"只是":["只: chỉ. 是: là. Chỉ là; đặt đầu vế sau còn nghĩa “nhưng”.",["我只是想看看，不买。","Wǒ zhǐshì xiǎng kànkan, bù mǎi.","Mình chỉ muốn xem thôi, không mua."]],
"啤酒":["啤 có bộ <b>口</b> + 卑 (âm “bi”) → phiên âm “beer”. 酒 có bộ <b>氵</b> + 酉 (bình rượu). Bia.",["冰箱里有啤酒。","Bīngxiāng li yǒu píjiǔ.","Trong tủ lạnh có bia."]],
"回":["Hai ô vuông lồng nhau → quay về. Lượng từ: vụ, lần (怎么回事: chuyện gì thế).",["这是怎么回事？","Zhè shì zěnme huí shì?","Chuyện này là sao vậy?"]],
"紧张":["紧 có bộ <b>糸</b> (sợi) → dây căng chặt. 张: kéo căng (bộ <b>弓</b>). Căng thẳng, hồi hộp.",["考试的时候我很紧张。","Kǎoshì de shíhou wǒ hěn jǐnzhāng.","Lúc thi mình rất hồi hộp."]],
"主要":["主: chủ (ngọn đèn có ngọn lửa). 要: quan trọng. Chủ yếu, chính.",["主要的问题是时间不够。","Zhǔyào de wèntí shì shíjiān bú gòu.","Vấn đề chính là không đủ thời gian."]],
"受到":["受: nhận (hai bàn tay trao nhận). 到: đến. Nhận được, chịu: 受到影响, 受到欢迎.",["这个电影受到了很多人的欢迎。","Zhège diànyǐng shòudàole hěn duō rén de huānyíng.","Bộ phim này được nhiều người yêu thích."]],
"影响":["影 có bộ <b>彡</b> (bóng, ánh sáng). 响 có bộ <b>口</b>: tiếng vang. Bóng và tiếng vang lan ra = ảnh hưởng.",["玩手机太多会影响学习。","Wán shǒujī tài duō huì yǐngxiǎng xuéxí.","Chơi điện thoại nhiều quá sẽ ảnh hưởng việc học."]],
"得分":["得 đọc <b>dé</b> = được. 分: điểm. Được điểm = ghi điểm, ghi bàn; cũng là tỉ số.",["他在比赛中得了十分。","Tā zài bǐsài zhōng déle shí fēn.","Anh ấy ghi được mười điểm trong trận đấu."]],
"体育":["体: thân thể (<b>亻</b> + 本). 育: nuôi dưỡng. Nuôi dưỡng thân thể = thể dục thể thao.",["我最喜欢上体育课。","Wǒ zuì xǐhuan shàng tǐyù kè.","Mình thích nhất giờ thể dục."]],
"世界":["世: đời. 界 có bộ <b>田</b> (ruộng) + 介: ranh giới. Thế giới.",["我想去世界上很多地方旅游。","Wǒ xiǎng qù shìjiè shang hěn duō dìfang lǚyóu.","Mình muốn đi du lịch nhiều nơi trên thế giới."]],
"运动员":["运动: thể thao. 员: người (bộ <b>口</b> + <b>贝</b>). Người chơi thể thao = vận động viên.",["他是一个网球运动员。","Tā shì yí ge wǎngqiú yùndòngyuán.","Anh ấy là vận động viên quần vợt."]],
"得到":["得 (dé): được. 到: đến tay. Đạt được, nhận được.",["她得到了一个好机会。","Tā dédàole yí ge hǎo jīhuì.","Cô ấy nhận được một cơ hội tốt."]],
"成绩":["成: thành. 绩 có bộ <b>纟</b> + 责: công lao dệt thành. Thành tích, kết quả học tập.",["这次考试他的成绩很好。","Zhè cì kǎoshì tā de chéngjì hěn hǎo.","Lần thi này điểm của cậu ấy rất tốt."]],
"奥运会":["奥: (phiên âm “Olympic”). 运: vận động. 会: hội. Thế vận hội Olympic.",["奥运会每四年一次。","Àoyùnhuì měi sì nián yí cì.","Olympic bốn năm tổ chức một lần."]],
"刘长春":["刘: họ Lưu (bộ <b>刂</b> dao). 长春: Trường Xuân. VĐV Trung Quốc đầu tiên dự Olympic (1932).",["刘长春是中国第一位参加奥运会的运动员。","Liú Chángchūn shì Zhōngguó dì-yī wèi cānjiā Àoyùnhuì de yùndòngyuán.","Lưu Trường Xuân là VĐV Trung Quốc đầu tiên dự Olympic."]]},
"3-10":{
"数学":["数 có bộ <b>攵</b> (tay cầm que) + 娄: đếm. 学: học. Môn học về đếm, tính = Toán. 数 đọc <b>shù</b>.",["我的数学不太好。","Wǒ de shùxué bú tài hǎo.","Môn Toán của mình không tốt lắm."]],
"认真":["认 có bộ <b>讠</b> (lời nói): nhận biết. 真: thật. Làm thật lòng = chăm chỉ, nghiêm túc.",["他上课非常认真。","Tā shàngkè fēicháng rènzhēn.","Cậu ấy học trên lớp rất chăm chú."]],
"笔记":["笔 có bộ <b>⺮</b> (tre): cây bút. 记 có bộ <b>讠</b>: ghi. Ghi bằng bút = ghi chép, vở ghi.",["你的笔记记得真清楚。","Nǐ de bǐjì jì de zhēn qīngchu.","Vở ghi của bạn ghi rõ ràng thật."]],
"清楚":["清 có bộ <b>氵</b> + 青: nước trong. 楚: rõ. Trong và rõ = rõ ràng. 楚 đọc nhẹ “chu”.",["我没听清楚，你再说一遍。","Wǒ méi tīng qīngchu, nǐ zài shuō yí biàn.","Mình nghe chưa rõ, bạn nói lại một lượt nhé."]],
"黑板":["黑: đen (bộ <b>灬</b> lửa, khói làm đen). 板 có bộ <b>木</b>: tấm gỗ. Tấm gỗ đen = bảng đen.",["老师在黑板上写字。","Lǎoshī zài hēibǎn shang xiě zì.","Cô giáo viết chữ lên bảng."]],
"把":["Bộ <b>扌</b> (tay) + 巴: tay nắm lấy → cầm, nắm. Giới từ: đưa tân ngữ lên trước động từ.",["请把门开开。","Qǐng bǎ mén kāikai.","Bạn mở cửa ra giúp nhé."]],
"作业":["作: làm (bộ <b>亻</b>). 业: việc, nghiệp. Việc phải làm = bài tập về nhà.",["今天的作业很多。","Jīntiān de zuòyè hěn duō.","Bài tập hôm nay nhiều quá."]],
"遍":["Bộ <b>辶</b> (đi) + 扁: đi khắp → lượt (từ đầu đến cuối). 看一遍, 说一遍.",["这个电影我看了三遍。","Zhège diànyǐng wǒ kànle sān biàn.","Bộ phim này mình xem ba lượt rồi."]],
"提高":["提 có bộ <b>扌</b> (tay): xách lên. 高: cao. Xách lên cao = nâng cao.",["我想提高我的汉语水平。","Wǒ xiǎng tígāo wǒ de Hànyǔ shuǐpíng.","Mình muốn nâng cao trình độ tiếng Trung."]],
"历史":["历: trải qua. 史: sử (tay cầm sổ ghi chép). Những gì đã trải qua được ghi lại = lịch sử.",["中国的历史很长。","Zhōngguó de lìshǐ hěn cháng.","Lịch sử Trung Quốc rất dài."]],
"难":["Bộ <b>隹</b> (chim đuôi ngắn) + 又. Chim bị tay bắt → gặp nạn → khó.",["汉字不难，多写就会了。","Hànzì bù nán, duō xiě jiù huì le.","Chữ Hán không khó, viết nhiều là biết."]],
"要求":["要: muốn, cần. 求: cầu xin. Yêu cầu, đòi hỏi.",["老师要求我们每天写作业。","Lǎoshī yāoqiú wǒmen měi tiān xiě zuòyè.","Cô yêu cầu chúng mình ngày nào cũng làm bài tập."]],
"差":["Đọc <b>chà</b> = kém, thiếu (khác 差不多 chàbuduō, 出差 chūchāi).",["我的汉字写得很差。","Wǒ de Hànzì xiě de hěn chà.","Chữ Hán mình viết rất kém."]],
"复习":["复: lặp lại, lại lần nữa. 习: học tập. Học lại = ôn tập.",["明天考试，今天晚上我要复习。","Míngtiān kǎoshì, jīntiān wǎnshang wǒ yào fùxí.","Mai thi, tối nay mình phải ôn bài."]],
"外语":["外: bên ngoài. 语 có bộ <b>讠</b>: lời nói. Tiếng nước ngoài = ngoại ngữ.",["你会说几门外语？","Nǐ huì shuō jǐ mén wàiyǔ?","Bạn nói được mấy ngoại ngữ?"]],
"当然":["当: nên, đáng. 然: như thế. Đáng như thế = đương nhiên.",["当然可以，你问吧。","Dāngrán kěyǐ, nǐ wèn ba.","Đương nhiên được, bạn hỏi đi."]],
"遇到":["遇 có bộ <b>辶</b> (đi) + 禺: đi đường gặp phải. 到: đến. Gặp, gặp phải.",["我在路上遇到了老师。","Wǒ zài lù shang yùdàole lǎoshī.","Mình gặp cô giáo trên đường."]],
"办公室":["办: làm (có bộ <b>力</b>). 公: việc chung. 室 có bộ <b>宀</b> (mái nhà): phòng. Phòng làm việc.",["老师在办公室。","Lǎoshī zài bàngōngshì.","Cô giáo ở văn phòng."]],
"页":["Hình đầu người → trang giấy. Là bộ <b>页</b> trong 题, 顾. Lượng từ: trang.",["请打开书，看第十页。","Qǐng dǎkāi shū, kàn dì-shí yè.","Mở sách ra, xem trang 10."]],
"对话":["对: đối diện. 话 có bộ <b>讠</b>: lời nói. Nói với nhau = đối thoại, hội thoại.",["我们来练习这个对话吧。","Wǒmen lái liànxí zhège duìhuà ba.","Chúng mình luyện đoạn hội thoại này nhé."]],
"明白":["明: <b>日</b> + <b>月</b> → sáng. 白: trắng, rõ. Sáng rõ = hiểu, rõ ràng. 白 đọc nhẹ “bai”.",["你明白我的意思吗？","Nǐ míngbai wǒ de yìsi ma?","Bạn hiểu ý mình không?"]],
"讲":["Bộ <b>讠</b> (lời nói) + 井: nói rõ ràng ngay ngắn → giảng, giải thích.",["老师讲得很清楚。","Lǎoshī jiǎng de hěn qīngchu.","Cô giảng rất rõ ràng."]],
"句":["Bộ <b>勹</b> (bao) + <b>口</b>: lời nói được gói lại → câu. Lượng từ: 一句话.",["我想说几句话。","Wǒ xiǎng shuō jǐ jù huà.","Tôi muốn nói vài câu."]],
"句子":["句: câu. 子: hậu tố danh từ (đọc nhẹ “zi”). Câu.",["这个句子是什么意思？","Zhège jùzi shì shénme yìsi?","Câu này nghĩa là gì?"]],
"年级":["年: năm. 级 có bộ <b>纟</b> + 及: bậc, cấp. Bậc học theo năm = khối lớp.",["我妹妹上三年级。","Wǒ mèimei shàng sān niánjí.","Em gái mình học lớp 3."]],
"后年":["后: sau. 年: năm. Năm sau nữa (sau 明年). So sánh: 后天 = ngày kia.",["我后年去中国留学。","Wǒ hòunián qù Zhōngguó liúxué.","Năm sau nữa mình đi Trung Quốc du học."]],
"一般":["一: một. 般: loại, kiểu. Cùng một kiểu = thông thường, bình thường. 一 đọc <b>yì</b>.",["我一般七点起床。","Wǒ yìbān qī diǎn qǐchuáng.","Mình thường dậy lúc 7 giờ."]],
"努力":["努 có bộ <b>力</b> + 奴. 力: sức. Dồn hết sức = nỗ lực, cố gắng.",["为了考上大学，她每天都很努力。","Wèile kǎoshang dàxué, tā měi tiān dōu hěn nǔlì.","Để đỗ đại học, ngày nào cô ấy cũng rất cố gắng."]]},
"3-11":{
"会议":["会: họp. 议 có bộ <b>讠</b>: bàn bạc. Họp bàn = cuộc họp, hội nghị.",["会议下午两点开始。","Huìyì xiàwǔ liǎng diǎn kāishǐ.","Cuộc họp bắt đầu lúc 2 giờ chiều."]],
"经理":["经: quản lý (bộ <b>纟</b>). 理 có bộ <b>王</b> (ngọc): sắp xếp. Người quản lý = giám đốc, quản lý.",["经理今天不在公司。","Jīnglǐ jīntiān bú zài gōngsī.","Hôm nay giám đốc không có ở công ty."]],
"开会":["开: mở. 会: cuộc họp. Mở cuộc họp = họp. Từ li hợp: 开了一个会.",["我们明天上午开会。","Wǒmen míngtiān shàngwǔ kāihuì.","Sáng mai chúng ta họp."]],
"后天":["后: sau. 天: ngày. Ngày sau ngày mai = ngày kia.",["后天是星期六。","Hòutiān shì xīngqīliù.","Ngày kia là thứ Bảy."]],
"地点":["地: đất, nơi (bộ <b>土</b>). 点: điểm (bộ <b>灬</b>). Nơi chốn = địa điểm.",["会议的地点在哪儿？","Huìyì de dìdiǎn zài nǎr?","Địa điểm họp ở đâu?"]],
"室":["Bộ <b>宀</b> (mái nhà) + 至 (đến): nơi đi đến dưới mái nhà → phòng. 教室, 会议室.",["会议室在三楼。","Huìyìshì zài sān lóu.","Phòng họp ở tầng 3."]],
"发":["Nghĩa gốc: bắn tên đi → phát ra, gửi đi. 发邮件 (gửi email), 发烧 (sốt).",["我给你发了一个邮件。","Wǒ gěi nǐ fāle yí ge yóujiàn.","Mình gửi cho bạn một email rồi."]],
"笔记本电脑":["笔记本: quyển vở ghi. 电脑: máy tính. Máy tính mỏng như cuốn vở = laptop.",["我的笔记本电脑很轻。","Wǒ de bǐjìběn diànnǎo hěn qīng.","Laptop của mình rất nhẹ."]],
"或者":["或: hoặc. 者: trợ từ. Hoặc là — dùng trong câu trần thuật (câu hỏi dùng 还是).",["你今天或者明天来都可以。","Nǐ jīntiān huòzhě míngtiān lái dōu kěyǐ.","Bạn đến hôm nay hoặc mai đều được."]],
"声音":["声: tiếng (士 trên, 尸 dưới). 音: âm (立 + 日). Âm thanh.",["你的声音太小了。","Nǐ de shēngyīn tài xiǎo le.","Giọng bạn nhỏ quá."]],
"看来":["看: nhìn. 来: đến. Nhìn mà suy ra = xem ra, có vẻ như. Khác 看起来 (trông có vẻ).",["看来要下雨了。","Kànlái yào xià yǔ le.","Xem ra sắp mưa rồi."]],
"办法":["办: làm (có bộ <b>力</b>). 法 có bộ <b>氵</b>: phép, cách. Cách làm = biện pháp.",["我们一起想办法吧。","Wǒmen yìqǐ xiǎng bànfǎ ba.","Chúng mình cùng nghĩ cách nhé."]],
"解决":["解: <b>角</b> (sừng) + <b>刀</b> + <b>牛</b>: dùng dao xẻ sừng bò → tháo gỡ. 决 có bộ <b>冫</b>: quyết. Giải quyết.",["这个问题很快就解决了。","Zhège wèntí hěn kuài jiù jiějué le.","Vấn đề này được giải quyết rất nhanh."]],
"只能":["只: chỉ. 能: có thể. Chỉ có thể (không còn cách khác).",["没有车了，我们只能走回去。","Méiyǒu chē le, wǒmen zhǐ néng zǒu huíqu.","Hết xe rồi, chúng mình chỉ có thể đi bộ về."]],
"别人":["别: khác (bộ <b>刂</b> dao: tách ra). 人: người. Người khác.",["别人都走了，只有我还在。","Biérén dōu zǒu le, zhǐ yǒu wǒ hái zài.","Người khác đi hết rồi, chỉ còn mình ở lại."]],
"请假":["请: xin (bộ <b>讠</b>). 假 đọc <b>jià</b> = kỳ nghỉ. Xin nghỉ. Từ li hợp: 请了两天假.",["我明天想请一天假。","Wǒ míngtiān xiǎng qǐng yì tiān jià.","Mai em muốn xin nghỉ một ngày."]],
"同事":["同: cùng. 事: việc. Người cùng làm việc = đồng nghiệp.",["我的同事都很热情。","Wǒ de tóngshì dōu hěn rèqíng.","Đồng nghiệp của mình đều rất nhiệt tình."]],
"休假":["休: <b>亻</b> dựa vào <b>木</b> (cây) → nghỉ ngơi. 假 (jià): kỳ nghỉ. Nghỉ phép.",["经理下个星期休假。","Jīnglǐ xià ge xīngqī xiūjià.","Tuần sau giám đốc nghỉ phép."]],
"怕":["Bộ <b>忄</b> (tim) + 白 (trắng): tim sợ đến trắng bệch → sợ.",["我怕说错话。","Wǒ pà shuōcuò huà.","Mình sợ nói sai."]],
"邮箱":["邮 có bộ <b>阝</b>: bưu điện. 箱 có bộ <b>⺮</b>: cái hòm. Hòm thư = hộp thư (điện tử).",["你的邮箱是多少？","Nǐ de yóuxiāng shì duōshao?","Địa chỉ email của bạn là gì?"]],
"老张":["老 + họ: cách gọi thân mật người lớn tuổi hơn hoặc đồng nghiệp lâu năm. 张: họ Trương.",["老张是我们公司的老同事。","Lǎo Zhāng shì wǒmen gōngsī de lǎo tóngshì.","Anh Trương là đồng nghiệp lâu năm của công ty mình."]],
"愿意":["愿 có bộ <b>心</b> + 原: mong muốn từ đáy lòng. 意 cũng có bộ <b>心</b>. Bằng lòng, sẵn lòng.",["你愿意跟我一起去吗？","Nǐ yuànyì gēn wǒ yìqǐ qù ma?","Bạn có muốn đi cùng mình không?"]],
"城市":["城 có bộ <b>土</b>: tường thành. 市 hình cái chợ. Thành và chợ = thành phố.",["河内是一个很漂亮的城市。","Hénèi shì yí ge hěn piàoliang de chéngshì.","Hà Nội là một thành phố rất đẹp."]],
"离开":["离: rời, cách. 开: mở ra, rời đi. Rời khỏi.",["他离开家已经三年了。","Tā líkāi jiā yǐjīng sān nián le.","Anh ấy rời nhà đã ba năm rồi."]],
"机会":["机: thời cơ (bộ <b>木</b>). 会: dịp gặp. Dịp may = cơ hội.",["这是一个很好的机会。","Zhè shì yí ge hěn hǎo de jīhuì.","Đây là một cơ hội rất tốt."]],
"生活":["生: sống, sinh ra. 活 có bộ <b>氵</b> (nước) + 舌: có nước là sống. Cuộc sống, sinh sống.",["我在河内生活了五年。","Wǒ zài Hénèi shēnghuóle wǔ nián.","Mình sống ở Hà Nội năm năm rồi."]],
"为":["Đọc <b>wèi</b> (thanh 4) = vì, cho (为工作, 为你). Khác 为 wéi trong 以为 (tưởng rằng).",["妈妈为我准备了早饭。","Māma wèi wǒ zhǔnbèi le zǎofàn.","Mẹ chuẩn bị bữa sáng cho mình."]],
"或":["Dạng ngắn của 或者, dùng nhiều trong văn viết. Có bộ <b>戈</b> (giáo).",["你可以打电话或发邮件。","Nǐ kěyǐ dǎ diànhuà huò fā yóujiàn.","Bạn có thể gọi điện hoặc gửi email."]]},
"3-12":{
"街":["Bộ <b>行</b> (đường đi) ôm hai chữ 土 ở giữa: đường có nhà cửa hai bên = phố.",["这条街上有很多饭馆。","Zhè tiáo jiē shang yǒu hěn duō fànguǎn.","Trên phố này có rất nhiều nhà hàng."]],
"开花":["开: mở. 花: hoa (bộ <b>艹</b>). Hoa mở ra = nở hoa.",["春天到了，树都开花了。","Chūntiān dào le, shù dōu kāihuā le.","Mùa xuân đến, cây đều nở hoa rồi."]],
"公园":["公: chung, công cộng. 园 có bộ <b>囗</b> (vây quanh): khu vườn có rào. Vườn chung = công viên.",["周末我们去公园玩儿吧。","Zhōumò wǒmen qù gōngyuán wánr ba.","Cuối tuần mình đi công viên chơi nhé."]],
"船":["Bộ <b>舟</b> (con thuyền) bên trái. Lượng từ: 一条船. 坐船: đi thuyền.",["我们在公园里坐船。","Wǒmen zài gōngyuán li zuò chuán.","Chúng mình đi thuyền trong công viên."]],
"工作日":["工作: làm việc. 日: ngày. Ngày làm việc (thứ Hai – thứ Sáu), trái với 周末.",["工作日我每天七点起床。","Gōngzuòrì wǒ měi tiān qī diǎn qǐchuáng.","Ngày làm việc ngày nào tôi cũng dậy lúc 7 giờ."]],
"地方":["地: đất (bộ <b>土</b>). 方: phương, hướng. Chỗ, nơi. 方 đọc nhẹ: dìfang.",["这个地方很漂亮。","Zhège dìfang hěn piàoliang.","Nơi này rất đẹp."]],
"刚才":["刚: vừa mới. 才: mới. Vừa rồi, lúc nãy (danh từ thời gian, đứng trước / sau chủ ngữ).",["刚才你去哪儿了？","Gāngcái nǐ qù nǎr le?","Lúc nãy bạn đi đâu thế?"]],
"刮":["Bộ <b>刂</b> (dao) bên phải: cạo, gọt → gió “cạo” qua mặt đất = gió thổi. 刮风.",["外面刮风了，多穿点儿衣服。","Wàimiàn guā fēng le, duō chuān diǎnr yīfu.","Ngoài trời có gió, mặc thêm áo vào."]],
"风":["Bộ <b>几</b> bao ngoài, bên trong là nét như luồng khí xoáy = gió.",["今天风很大。","Jīntiān fēng hěn dà.","Hôm nay gió rất to."]],
"新闻":["新: mới. 闻: nghe (耳 trong 门): nghe được tin. Tin mới nghe = tin tức.",["我每天早上看新闻。","Wǒ měi tiān zǎoshang kàn xīnwén.","Sáng nào tôi cũng xem tin tức."]],
"伞":["Nhìn như chiếc ô: mái che 人 ở trên, cán thẳng ở giữa. 雨伞: ô che mưa.",["下雨了，你带伞了吗？","Xià yǔ le, nǐ dài sǎn le ma?","Mưa rồi, bạn có mang ô không?"]],
"借":["Bộ <b>亻</b> (người) + 昔: việc giữa người với người → mượn, cho mượn. 借给 + người.",["我可以借你的词典吗？","Wǒ kěyǐ jiè nǐ de cídiǎn ma?","Mình mượn từ điển của bạn được không?"]],
"把":["Bộ <b>扌</b> (tay): cầm, nắm. Lượng từ cho vật có tay cầm: 一把伞, 一把椅子.",["我车里有一把伞。","Wǒ chē li yǒu yì bǎ sǎn.","Trong xe tôi có một cái ô."]],
"雨衣":["雨: mưa. 衣: áo (bộ <b>衣</b>). Áo đi mưa. Lượng từ: 一件雨衣.",["骑车的时候要穿雨衣。","Qí chē de shíhou yào chuān yǔyī.","Lúc đi xe phải mặc áo mưa."]],
"变":["Phần trên 亦, dưới 又 (bàn tay): tay làm đổi khác đi = thay đổi. 变好, 变冷.",["天气变冷了。","Tiānqì biàn lěng le.","Trời trở lạnh rồi."]],
"季节":["季: mùa (禾 lúa + 子): mùa vụ. 节: đốt, tiết (bộ <b>艹</b>). Mùa trong năm.",["你最喜欢哪个季节？","Nǐ zuì xǐhuan nǎge jìjié?","Bạn thích mùa nào nhất?"]],
"变化":["变: đổi. 化: hóa (bộ <b>亻</b>). Biến hóa = thay đổi, sự thay đổi.",["这几年河内的变化很大。","Zhè jǐ nián Hénèi de biànhuà hěn dà.","Mấy năm nay Hà Nội thay đổi rất nhiều."]],
"冬天":["冬: mùa đông, dưới có hai chấm <b>冫</b> như băng giá. 天: trời, mùa.",["冬天河内也有点儿冷。","Dōngtiān Hénèi yě yǒudiǎnr lěng.","Mùa đông Hà Nội cũng hơi lạnh."]],
"常常":["常: thường (bộ <b>巾</b>). Lặp lại 常常 = thường xuyên, đứng trước động từ.",["我常常去图书馆看书。","Wǒ chángcháng qù túshūguǎn kàn shū.","Tôi thường đến thư viện đọc sách."]],
"关注":["关: liên quan, để ý. 注: chú ý (bộ <b>氵</b>). Để ý theo dõi = quan tâm.",["我很关注天气。","Wǒ hěn guānzhù tiānqì.","Tôi rất quan tâm đến thời tiết."]],
"四季":["四: bốn. 季: mùa. Bốn mùa xuân hạ thu đông.",["这里四季都很漂亮。","Zhèlǐ sìjì dōu hěn piàoliang.","Nơi này bốn mùa đều đẹp."]],
"春天":["春: mùa xuân, dưới có 日 (mặt trời) ấm áp. Mùa xuân.",["春天的花很漂亮。","Chūntiān de huā hěn piàoliang.","Hoa mùa xuân rất đẹp."]],
"夏天":["夏: mùa hè. 夏天 nóng nhất trong năm.",["夏天我喜欢去海边。","Xiàtiān wǒ xǐhuan qù hǎibiān.","Mùa hè tôi thích đi biển."]],
"凉快":["凉: mát, có bộ <b>冫</b> (băng, lạnh). 快: dễ chịu. Mát mẻ, dễ chịu. 快 đọc nhẹ.",["晚上比较凉快。","Wǎnshang bǐjiào liángkuai.","Buổi tối khá mát mẻ."]],
"秋天":["秋: mùa thu, có 禾 (lúa) + 火 (lửa): mùa lúa chín vàng như lửa.",["秋天是河内最舒服的季节。","Qiūtiān shì Hénèi zuì shūfu de jìjié.","Mùa thu là mùa dễ chịu nhất ở Hà Nội."]],
"叶子":["叶: lá (口 + 十). 子: hậu tố danh từ, đọc nhẹ. Chiếc lá.",["秋天的叶子变黄了。","Qiūtiān de yèzi biàn huáng le.","Lá mùa thu chuyển vàng rồi."]],
"变成":["变: đổi. 成: thành. Biến thành, trở thành + kết quả.",["水变成了冰。","Shuǐ biànchéngle bīng.","Nước biến thành băng."]]},
"3-13":{
"请客":["请: mời (bộ <b>讠</b>). 客: khách. Mời khách = đãi, bao (trả tiền). 我请客!",["今天我请客，大家别客气。","Jīntiān wǒ qǐngkè, dàjiā bié kèqi.","Hôm nay mình mời, mọi người đừng khách sáo."]],
"南方":["南: phía nam. 方: phương. Phương nam, miền Nam.",["我是南方人。","Wǒ shì nánfāng rén.","Tôi là người miền Nam."]],
"北方":["北: phía bắc (hai người quay lưng nhau). 方: phương. Miền Bắc.",["北方的冬天很冷。","Běifāng de dōngtiān hěn lěng.","Mùa đông miền Bắc rất lạnh."]],
"做法":["做: làm. 法: phép, cách (bộ <b>氵</b>). Cách làm.",["这个菜的做法很简单。","Zhège cài de zuòfǎ hěn jiǎndān.","Cách làm món này rất đơn giản."]],
"不同":["不: không. 同: giống, cùng. Không giống = khác nhau. A 跟 B 不同.",["我们的想法不同。","Wǒmen de xiǎngfǎ bù tóng.","Suy nghĩ của chúng ta khác nhau."]],
"加":["力 (sức) + 口: thêm sức, thêm vào. 再加一个菜: gọi thêm một món.",["再加一个鸡肉吧。","Zài jiā yí ge jīròu ba.","Gọi thêm một món gà nữa nhé."]],
"的话":["Đặt cuối vế giả thiết: ……的话 = nếu … Thường đi với 就 ở vế sau.",["下雨的话，我们就不去了。","Xià yǔ dehuà, wǒmen jiù bú qù le.","Nếu mưa thì chúng ta không đi nữa."]],
"做客":["做: làm. 客: khách (bộ <b>宀</b> mái nhà). Làm khách = đến nhà người khác chơi.",["周末我去朋友家做客。","Zhōumò wǒ qù péngyou jiā zuòkè.","Cuối tuần tôi đến nhà bạn chơi."]],
"邻居":["邻: láng giềng (bộ <b>阝</b> bên phải: làng). 居: ở. Người ở gần = hàng xóm.",["我的邻居很热情。","Wǒ de línjū hěn rèqíng.","Hàng xóm của tôi rất nhiệt tình."]],
"放心":["放: thả, buông. 心: tim, lòng. Buông lòng ra = yên tâm. 放心吧!",["放心吧，我会准时到的。","Fàngxīn ba, wǒ huì zhǔnshí dào de.","Yên tâm đi, mình sẽ đến đúng giờ."]],
"酒":["Bộ <b>氵</b> (nước) + 酉 (vò rượu): nước trong vò = rượu.",["他不喝酒。","Tā bù hē jiǔ.","Anh ấy không uống rượu."]],
"放":["Bộ <b>攵</b> (tay cầm gậy): đặt, để. 放在 + nơi chốn, 放进 + nơi chốn.",["你把书放在桌子上吧。","Nǐ bǎ shū fàng zài zhuōzi shang ba.","Bạn để sách lên bàn nhé."]],
"客人":["客: khách. 人: người. Người khách, khách hàng.",["客人快到了。","Kèrén kuài dào le.","Khách sắp đến rồi."]],
"晚会":["晚: buổi tối (bộ <b>日</b>). 会: cuộc họp mặt. Buổi họp mặt buổi tối = dạ hội.",["学校明天有晚会。","Xuéxiào míngtiān yǒu wǎnhuì.","Ngày mai trường có dạ hội."]],
"礼物":["礼: lễ (bộ <b>礻</b>). 物: vật (bộ <b>牛</b>). Vật thể hiện lễ nghĩa = quà.",["这是送你的生日礼物。","Zhè shì sòng nǐ de shēngrì lǐwù.","Đây là quà sinh nhật tặng bạn."]],
"画家":["画: vẽ. 家: nhà (chuyên gia). Hậu tố 家 = người giỏi trong lĩnh vực. Họa sĩ.",["她想做一名画家。","Tā xiǎng zuò yì míng huàjiā.","Cô ấy muốn trở thành họa sĩ."]],
"盘子":["盘: mâm, đĩa, dưới có bộ <b>皿</b> (đồ đựng). 子 đọc nhẹ. Cái đĩa.",["请把盘子拿过来。","Qǐng bǎ pánzi ná guòlai.","Làm ơn mang đĩa lại đây."]],
"一边":["一: một. 边: bên. 一边……一边…… = vừa … vừa …",["他一边吃饭一边看手机。","Tā yìbiān chī fàn yìbiān kàn shǒujī.","Anh ấy vừa ăn cơm vừa xem điện thoại."]],
"聊天儿":["聊: tán chuyện, có bộ <b>耳</b> (tai). 天: trời. Nói chuyện trên trời dưới biển = tán gẫu.",["我们在咖啡馆聊天儿。","Wǒmen zài kāfēiguǎn liáotiānr.","Chúng tôi trò chuyện ở quán cà phê."]],
"来自":["来: đến. 自: từ. 来自 + nơi chốn = đến từ (trang trọng hơn 从……来).",["他来自越南。","Tā láizì Yuènán.","Anh ấy đến từ Việt Nam."]],
"夫妻":["夫: chồng. 妻: vợ, có bộ <b>女</b>. Vợ chồng.",["他们是一对年轻的夫妻。","Tāmen shì yí duì niánqīng de fūqī.","Họ là một cặp vợ chồng trẻ."]],
"直到":["直: thẳng. 到: đến. Thẳng cho đến = mãi đến (thường đi với 才).",["他直到十二点才睡觉。","Tā zhídào shí'èr diǎn cái shuìjiào.","Mãi đến 12 giờ anh ấy mới ngủ."]],
"地图":["地: đất. 图: hình vẽ (bộ <b>囗</b> khung bao). Hình vẽ mặt đất = bản đồ.",["我用手机地图找路。","Wǒ yòng shǒujī dìtú zhǎo lù.","Tôi dùng bản đồ điện thoại để tìm đường."]],
"点":["Bộ <b>灬</b> (bốn chấm) ở dưới: chấm, điểm nhỏ. Còn nghĩa: giờ (三点), gọi món (点菜).",["地图上的红点是我去过的地方。","Dìtú shang de hóng diǎn shì wǒ qùguo de dìfang.","Chấm đỏ trên bản đồ là nơi tôi từng đến."]],
"感到":["感: cảm (bộ <b>心</b>). 到: đến. Cảm thấy + tính từ / sự việc.",["我感到很高兴。","Wǒ gǎndào hěn gāoxìng.","Tôi cảm thấy rất vui."]],
"东方":["东: phía đông (mặt trời 日 mọc sau cây 木). 方: phương. Phương Đông.",["他对东方文化很感兴趣。","Tā duì dōngfāng wénhuà hěn gǎn xìngqù.","Anh ấy rất hứng thú với văn hóa phương Đông."]],
"文化":["文: văn, chữ. 化: hóa. Văn hóa.",["我喜欢了解中国文化。","Wǒ xǐhuan liǎojiě Zhōngguó wénhuà.","Tôi thích tìm hiểu văn hóa Trung Quốc."]],
"英国":["英: anh hoa (bộ <b>艹</b>). 国: nước. Nước Anh.",["我的老师来自英国。","Wǒ de lǎoshī láizì Yīngguó.","Giáo viên của tôi đến từ Anh."]]},
"3-14":{
"词典":["词: từ (bộ <b>讠</b>). 典: sách quý, điển. Sách tra từ = từ điển.",["这个字你可以查词典。","Zhège zì nǐ kěyǐ chá cídiǎn.","Chữ này bạn có thể tra từ điển."]],
"最好":["最: nhất. 好: tốt. Đứng trước động từ: tốt nhất là nên …",["你最好早点儿来。","Nǐ zuìhǎo zǎo diǎnr lái.","Tốt nhất bạn nên đến sớm một chút."]],
"节":["Bộ <b>艹</b> trên: đốt tre, tiết. Lượng từ cho tiết học: 两节课.",["今天上午有四节课。","Jīntiān shàngwǔ yǒu sì jié kè.","Sáng nay có bốn tiết học."]],
"图书馆":["图: tranh. 书: sách. 馆: tòa nhà (bộ <b>饣</b>). Nơi chứa tranh sách = thư viện.",["我在图书馆看书。","Wǒ zài túshūguǎn kàn shū.","Tôi đọc sách ở thư viện."]],
"被":["Bộ <b>衤</b> (áo) + 皮 (da): nghĩa gốc chăn đắp → bị trùm lên → bị, được (bị động).",["我的手机被弟弟拿走了。","Wǒ de shǒujī bèi dìdi názǒu le.","Điện thoại của tôi bị em trai cầm đi rồi."]],
"名人":["名: tên, nổi tiếng. 人: người. Người có tên tuổi = danh nhân.",["他是一个名人。","Tā shì yí ge míngrén.","Anh ấy là người nổi tiếng."]],
"故事":["故: cũ, xưa. 事: việc. Chuyện ngày xưa = câu chuyện. 事 đọc nhẹ: gùshi.",["妈妈每天给我讲故事。","Māma měi tiān gěi wǒ jiǎng gùshi.","Mẹ ngày nào cũng kể chuyện cho tôi."]],
"然后":["然: như thế. 后: sau. Sau đó, đứng đầu vế sau: 先……，然后…….",["我先吃饭，然后去上班。","Wǒ xiān chī fàn, ránhòu qù shàngbān.","Tôi ăn cơm trước, sau đó đi làm."]],
"报纸":["报: báo (bộ <b>扌</b>). 纸: giấy (bộ <b>纟</b>). Giấy báo = tờ báo.",["爷爷每天早上看报纸。","Yéye měi tiān zǎoshang kàn bàozhǐ.","Ông sáng nào cũng đọc báo."]],
"忘记":["忘: quên, có bộ <b>心</b> (tim): lòng mất đi. 记: nhớ. Quên.",["我忘记带钥匙了。","Wǒ wàngjì dài yàoshi le.","Tôi quên mang chìa khóa rồi."]],
"电子书":["电子: điện tử. 书: sách. Sách điện tử.",["我常常用手机看电子书。","Wǒ chángcháng yòng shǒujī kàn diànzǐshū.","Tôi thường đọc sách điện tử bằng điện thoại."]],
"女生":["女: nữ. 生: học sinh. Nữ sinh, bạn nữ.",["我们班有十个女生。","Wǒmen bān yǒu shí ge nǚshēng.","Lớp tôi có mười bạn nữ."]],
"表演":["表: biểu, thể hiện. 演: diễn (bộ <b>氵</b>). Biểu diễn.",["他们在晚会上表演跳舞。","Tāmen zài wǎnhuì shang biǎoyǎn tiàowǔ.","Họ biểu diễn nhảy ở dạ hội."]],
"节目":["节: tiết. 目: mục (con mắt). Tiết mục, chương trình.",["这个节目很有意思。","Zhège jiémù hěn yǒu yìsi.","Tiết mục này rất thú vị."]],
"怎么办":["怎么: thế nào. 办: làm, xử lý. Phải làm sao đây?",["我的钱包不见了，怎么办？","Wǒ de qiánbāo bú jiàn le, zěnme bàn?","Ví của mình mất rồi, làm sao đây?"]],
"校长":["校: trường (bộ <b>木</b>). 长: người đứng đầu (đọc zhǎng). Hiệu trưởng.",["校长在办公室。","Xiàozhǎng zài bàngōngshì.","Hiệu trưởng ở văn phòng."]],
"面前":["面: mặt. 前: trước. Trước mặt. 在 + người + 面前.",["在老师面前，他有点儿紧张。","Zài lǎoshī miànqián, tā yǒudiǎnr jǐnzhāng.","Trước mặt thầy, cậu ấy hơi căng thẳng."]],
"有些":["有: có. 些: một vài. Có một số; đứng trước tính từ = hơi (有些紧张).",["今天我有些累。","Jīntiān wǒ yǒuxiē lèi.","Hôm nay tôi hơi mệt."]],
"相信":["相: lẫn nhau. 信: tin (亻 người + 言 lời nói: lời người nói đáng tin). Tin tưởng.",["我相信你一定能考好。","Wǒ xiāngxìn nǐ yídìng néng kǎohǎo.","Mình tin bạn chắc chắn sẽ thi tốt."]],
"新年":["新: mới. 年: năm. Năm mới. 新年快乐!",["新年快乐！","Xīnnián kuàilè!","Chúc mừng năm mới!"]],
"班级":["班: lớp (王 ở hai bên, 刂 ở giữa). 级: cấp (bộ <b>纟</b>). Lớp học.",["每个班级都有三十个学生。","Měi ge bānjí dōu yǒu sānshí ge xuésheng.","Mỗi lớp đều có ba mươi học sinh."]],
"跳":["Bộ <b>⻊</b> (chân) bên trái: dùng chân → nhảy. 跳舞: nhảy múa.",["她跳得很高。","Tā tiào de hěn gāo.","Cô ấy nhảy rất cao."]],
"留学生":["留: ở lại. 学: học. 生: học sinh. Người ở lại nước ngoài học = lưu học sinh.",["我们学校有很多留学生。","Wǒmen xuéxiào yǒu hěn duō liúxuéshēng.","Trường tôi có nhiều lưu học sinh."]],
"最后":["最: nhất. 后: sau. Sau cùng = cuối cùng.",["最后一个节目是唱歌。","Zuìhòu yí ge jiémù shì chàng gē.","Tiết mục cuối cùng là hát."]],
"一块儿":["一: một. 块: khối, chỗ. Cùng một chỗ = cùng nhau (khẩu ngữ, giống 一起).",["我们一块儿去吃饭吧。","Wǒmen yíkuàir qù chī fàn ba.","Chúng mình cùng đi ăn nhé."]],
"网站":["网: mạng (lưới). 站: trạm, trang. Trang web.",["这个网站可以学汉语。","Zhège wǎngzhàn kěyǐ xué Hànyǔ.","Trang web này có thể học tiếng Trung."]],
"视频":["视: nhìn (bộ <b>礻</b> + 见). 频: tần số. Đoạn phim, video.",["我在网上看了一个视频。","Wǒ zài wǎng shang kànle yí ge shìpín.","Tôi đã xem một video trên mạng."]]},
"3-15":{
"蓝":["Bộ <b>艹</b> (cỏ) trên + 监: cây chàm nhuộm vải → màu xanh lam. 蓝天: trời xanh.",["今天的天特别蓝。","Jīntiān de tiān tèbié lán.","Hôm nay trời xanh đặc biệt."]],
"段":["Bên phải bộ <b>殳</b> (cầm gậy gõ): chặt ra từng đoạn. 一段时间: một khoảng thời gian.",["我在北京住过一段时间。","Wǒ zài Běijīng zhùguo yí duàn shíjiān.","Tôi từng sống ở Bắc Kinh một thời gian."]],
"附近":["附: bám vào (bộ <b>阝</b>). 近: gần (bộ <b>辶</b> đi). Bám sát gần đó = lân cận.",["我家附近有一个超市。","Wǒ jiā fùjìn yǒu yí ge chāoshì.","Gần nhà tôi có một siêu thị."]],
"马路":["马: ngựa. 路: đường (bộ <b>足</b>). Đường cho ngựa xe chạy = đường cái.",["过马路的时候要小心。","Guò mǎlù de shíhou yào xiǎoxīn.","Khi qua đường phải cẩn thận."]],
"平时":["平: bằng phẳng, bình thường. 时: lúc (bộ <b>日</b>). Lúc bình thường = thường ngày.",["你平时几点起床？","Nǐ píngshí jǐ diǎn qǐchuáng?","Bình thường bạn mấy giờ dậy?"]],
"放学":["放: thả ra (bộ <b>攵</b>). 学: học. Thả học sinh về = tan học.",["孩子们四点半放学。","Háizimen sì diǎn bàn fàngxué.","Bọn trẻ tan học lúc bốn rưỡi."]],
"游戏":["游: bơi, chơi (bộ <b>氵</b>). 戏: trò, kịch (bộ <b>戈</b>). Trò chơi. 做游戏 / 玩游戏.",["孩子们在草地上做游戏。","Háizimen zài cǎodì shang zuò yóuxì.","Bọn trẻ chơi trò chơi trên bãi cỏ."]],
"老人":["老: già. 人: người. Người già.",["这个小区有很多老人。","Zhège xiǎoqū yǒu hěn duō lǎorén.","Khu này có nhiều người già."]],
"根据":["根: rễ cây (bộ <b>木</b>). 据: dựa vào (bộ <b>扌</b>). Dựa vào gốc rễ = căn cứ vào.",["老师根据我们的水平上课。","Lǎoshī gēnjù wǒmen de shuǐpíng shàngkè.","Cô giáo dạy theo trình độ của chúng tôi."]],
"了解":["了: hiểu rõ (đọc liǎo). 解: tháo gỡ, giải. Gỡ ra cho rõ = hiểu rõ, tìm hiểu.",["我不太了解这个城市。","Wǒ bú tài liǎojiě zhège chéngshì.","Tôi không hiểu rõ thành phố này lắm."]],
"可是":["可: có thể. 是: là. Đứng đầu vế sau, giống 但是: nhưng.",["我很想去，可是没有时间。","Wǒ hěn xiǎng qù, kěshì méiyǒu shíjiān.","Tôi rất muốn đi, nhưng không có thời gian."]],
"以上":["以: lấy làm mốc. 上: trên. Từ mốc trở lên. 十岁以上: từ 10 tuổi trở lên.",["这个学校有一千个以上的学生。","Zhège xuéxiào yǒu yìqiān ge yǐshàng de xuésheng.","Trường này có hơn một nghìn học sinh."]],
"有名":["有: có. 名: tên. Có tên tuổi = nổi tiếng.",["这家饭馆很有名。","Zhè jiā fànguǎn hěn yǒumíng.","Nhà hàng này rất nổi tiếng."]],
"景点":["景: cảnh (bộ <b>日</b> trên: có nắng mới thấy cảnh). 点: điểm. Điểm ngắm cảnh = điểm du lịch.",["北京有很多有名的景点。","Běijīng yǒu hěn duō yǒumíng de jǐngdiǎn.","Bắc Kinh có nhiều điểm du lịch nổi tiếng."]],
"游客":["游: đi chơi (bộ <b>氵</b>). 客: khách (bộ <b>宀</b> mái nhà). Khách đi chơi = du khách.",["夏天这里的游客特别多。","Xiàtiān zhèlǐ de yóukè tèbié duō.","Mùa hè ở đây du khách rất đông."]],
"外地":["外: ngoài. 地: đất (bộ <b>土</b>). Đất bên ngoài = nơi khác. 外地人: người nơi khác.",["他是外地人，不太了解这里。","Tā shì wàidì rén, bú tài liǎojiě zhèlǐ.","Anh ấy là người nơi khác, không rành ở đây."]],
"聊":["Bộ <b>耳</b> (tai): nghe nhau nói → trò chuyện. 聊天儿: tán gẫu.",["我们边喝茶边聊。","Wǒmen biān hē chá biān liáo.","Chúng ta vừa uống trà vừa nói chuyện."]],
"南京":["南: nam. 京: kinh đô. Kinh đô phía nam = Nam Kinh (so với 北京 phía bắc).",["南京有两千年以上的历史。","Nánjīng yǒu liǎngqiān nián yǐshàng de lìshǐ.","Nam Kinh có lịch sử hơn 2000 năm."]],
"河":["Bộ <b>氵</b> (nước) + 可 (đọc gần hé): dòng nước = sông.",["我家旁边有一条河。","Wǒ jiā pángbiān yǒu yì tiáo hé.","Cạnh nhà tôi có một con sông."]],
"关系":["关: cửa, liên quan. 系: buộc, nối (bộ <b>糸</b>). Nối liền nhau = quan hệ. 跟……有关系.",["这件事跟我没有关系。","Zhè jiàn shì gēn wǒ méiyǒu guānxi.","Chuyện này không liên quan đến tôi."]],
"养":["Trên là 羊 (con dê) biến thể: chăn nuôi dê → nuôi, nuôi dưỡng.",["她家养了一只小狗。","Tā jiā yǎngle yì zhī xiǎo gǒu.","Nhà cô ấy nuôi một chú chó nhỏ."]],
"黄河":["黄: màu vàng. 河: sông. Nước sông có màu vàng = Hoàng Hà.",["黄河是中国很重要的河。","Huáng Hé shì Zhōngguó hěn zhòngyào de hé.","Hoàng Hà là con sông rất quan trọng của Trung Quốc."]],
"西北":["西: tây. 北: bắc. Tiếng Trung nói tây trước bắc: 西北 = tây bắc (giống tiếng Việt).",["我的老家在中国西北。","Wǒ de lǎojiā zài Zhōngguó xīběi.","Quê tôi ở tây bắc Trung Quốc."]],
"经过":["经: đi qua (bộ <b>纟</b>). 过: qua (bộ <b>辶</b>). Đi qua, trải qua.",["去学校要经过一个公园。","Qù xuéxiào yào jīngguò yí ge gōngyuán.","Đến trường phải đi qua một công viên."]],
"草地":["草: cỏ (bộ <b>艹</b>). 地: đất. Đất có cỏ = bãi cỏ.",["孩子们在草地上玩儿。","Háizimen zài cǎodì shang wánr.","Bọn trẻ chơi trên bãi cỏ."]],
"遇见":["遇: gặp (bộ <b>辶</b> đi đường). 见: thấy. Đang đi thì gặp = tình cờ gặp.",["我在超市遇见了我的老师。","Wǒ zài chāoshì yùjiànle wǒ de lǎoshī.","Tôi tình cờ gặp cô giáo ở siêu thị."]]},
"3-16":{
"脏":["Bộ <b>月</b> (thịt, cơ thể) + 庄: người lấm lem = bẩn.",["你的鞋太脏了，快去洗洗。","Nǐ de xié tài zāng le, kuài qù xǐxi.","Giày của bạn bẩn quá, mau đi rửa đi."]],
"可爱":["可: đáng, có thể. 爱: yêu. Đáng để yêu = đáng yêu.",["这只小狗真可爱。","Zhè zhī xiǎo gǒu zhēn kě'ài.","Chú chó con này đáng yêu thật."]],
"一会儿":["一: một. 会儿: lúc. Một lúc, một lát. 一会儿……一会儿……: lúc thì … lúc thì ….",["请等一会儿，我马上来。","Qǐng děng yíhuìr, wǒ mǎshàng lái.","Xin đợi một lát, tôi đến ngay."]],
"脚":["Bộ <b>月</b> (cơ thể) + 却: bộ phận đi lại = chân, bàn chân.",["我的脚有点儿疼。","Wǒ de jiǎo yǒudiǎnr téng.","Chân tôi hơi đau."]],
"照顾":["照: chiếu, soi (bộ <b>灬</b> lửa dưới). 顾: trông nom (bộ <b>页</b> đầu). Để mắt trông nom = chăm sóc.",["妈妈病了，我在家照顾她。","Māma bìng le, wǒ zài jiā zhàogù tā.","Mẹ ốm, tôi ở nhà chăm sóc mẹ."]],
"好像":["好: tốt, rất. 像: giống (bộ <b>亻</b>). Rất giống = dường như.",["他好像不太高兴。","Tā hǎoxiàng bú tài gāoxìng.","Anh ấy dường như không vui lắm."]],
"认得":["认: nhận (bộ <b>讠</b> lời nói). 得: được. Nhận ra được, quen biết.",["你还认得我吗？","Nǐ hái rènde wǒ ma?","Bạn còn nhận ra tôi không?"]],
"周末":["周: tuần. 末: cuối (bộ <b>木</b>, nét ngang trên dài: ngọn cây = phần cuối). Cuối tuần.",["周末你想去哪儿玩儿？","Zhōumò nǐ xiǎng qù nǎr wánr?","Cuối tuần bạn muốn đi đâu chơi?"]],
"动物园":["动物: động vật. 园: vườn (bộ <b>囗</b> rào quanh). Vườn động vật = sở thú.",["孩子们都喜欢去动物园。","Háizimen dōu xǐhuan qù dòngwùyuán.","Bọn trẻ đều thích đi sở thú."]],
"动物":["动: động (bộ <b>力</b> sức). 物: vật (bộ <b>牛</b>). Vật biết cử động = động vật.",["你最喜欢什么动物？","Nǐ zuì xǐhuan shénme dòngwù?","Bạn thích con vật nào nhất?"]],
"大熊猫":["大: lớn. 熊: gấu (bộ <b>灬</b>). 猫: mèo (bộ <b>犭</b>). Gấu to giống mèo = gấu trúc.",["大熊猫喜欢吃竹子。","Dàxióngmāo xǐhuan chī zhúzi.","Gấu trúc thích ăn tre."]],
"奇怪":["奇: lạ. 怪: quái (bộ <b>忄</b> tâm: thấy lạ trong lòng). Kỳ lạ.",["这个人说话很奇怪。","Zhège rén shuōhuà hěn qíguài.","Người này nói chuyện rất kỳ lạ."]],
"其实":["其: cái đó. 实: thực (bộ <b>宀</b>). Cái thực ra là = thực ra.",["他看起来很年轻，其实已经五十岁了。","Tā kàn qǐlai hěn niánqīng, qíshí yǐjīng wǔshí suì le.","Ông ấy trông rất trẻ, thực ra đã 50 tuổi rồi."]],
"竹子":["竹: hai cành tre có lá = cây tre (dạng bộ <b>⺮</b> trên đầu chữ 笔, 等…).",["这里有很多竹子。","Zhèlǐ yǒu hěn duō zhúzi.","Ở đây có rất nhiều tre."]],
"国宝":["国: nước. 宝: báu (bộ <b>宀</b> + 玉 ngọc: ngọc cất trong nhà). Báu vật của nước = quốc bảo.",["大熊猫是中国的国宝。","Dàxióngmāo shì Zhōngguó de guóbǎo.","Gấu trúc là quốc bảo của Trung Quốc."]],
"全":["人 trên + 王 (ngọc) dưới: ngọc nguyên vẹn = toàn bộ. 全世界: toàn thế giới.",["全班同学都来了。","Quán bān tóngxué dōu lái le.","Cả lớp đều đến rồi."]],
"野生":["野: đồng hoang (bộ <b>里</b>). 生: sống. Sống ngoài hoang = hoang dã.",["这里有很多野生动物。","Zhèlǐ yǒu hěn duō yěshēng dòngwù.","Ở đây có nhiều động vật hoang dã."]],
"关于":["关: liên quan. 于: ở, về. 关于 + N: về …. Nhớ: 关于 đặt trước danh từ.",["这是一本关于中国历史的书。","Zhè shì yì běn guānyú Zhōngguó lìshǐ de shū.","Đây là một quyển sách về lịch sử Trung Quốc."]],
"饱":["Bộ <b>饣</b> (ăn) + 包 (bao bọc): ăn đầy bụng = no.",["我吃饱了，谢谢！","Wǒ chībǎo le, xièxie!","Tôi ăn no rồi, cảm ơn!"]],
"张":["Bộ <b>弓</b> (cung) + 长: kéo căng dây cung = giương, mở ra. 张嘴: há miệng. Cũng là lượng từ: 一张照片.",["请张开嘴，我看看。","Qǐng zhāngkāi zuǐ, wǒ kànkan.","Hãy há miệng ra, để tôi xem."]],
"嘴":["Bộ <b>口</b> (miệng) + 觜: cái miệng.",["他的嘴很大。","Tā de zuǐ hěn dà.","Miệng cậu ấy rất to."]],
"身边":["身: thân mình. 边: bên (bộ <b>辶</b>). Bên cạnh mình.",["妈妈一直在我身边。","Māma yìzhí zài wǒ shēnbiān.","Mẹ luôn ở bên cạnh tôi."]],
"半天":["半: nửa. 天: ngày. Nửa ngày; khẩu ngữ: một lúc lâu.",["我等了你半天了！","Wǒ děngle nǐ bàntiān le!","Mình đợi bạn mãi rồi!"]],
"脸":["Bộ <b>月</b> (cơ thể) + 佥: mặt, khuôn mặt.",["她的脸红了。","Tā de liǎn hóng le.","Mặt cô ấy đỏ lên."]],
"大人":["大: lớn. 人: người. Người lớn (đọc dàren, 人 nhẹ).",["这个电影大人和孩子都喜欢。","Zhège diànyǐng dàren hé háizi dōu xǐhuan.","Bộ phim này người lớn và trẻ con đều thích."]],
"喜爱":["喜: vui thích. 爱: yêu. Yêu thích (trang trọng hơn 喜欢).",["这是孩子们最喜爱的游戏。","Zhè shì háizimen zuì xǐ'ài de yóuxì.","Đây là trò chơi bọn trẻ yêu thích nhất."]]},
"3-17":{
"向":["Mái nhà có ô cửa sổ 口 nhìn ra ngoài: hướng về. 向前走: đi về phía trước. 向……学习: học hỏi từ ….",["我们要向他学习。","Wǒmen yào xiàng tā xuéxí.","Chúng ta phải học hỏi anh ấy."]],
"楼梯":["楼: tầng lầu (bộ <b>木</b>). 梯: thang (bộ <b>木</b>, thang làm bằng gỗ). Cầu thang bộ.",["电梯坏了，我们走楼梯吧。","Diàntī huài le, wǒmen zǒu lóutī ba.","Thang máy hỏng rồi, chúng ta đi cầu thang bộ nhé."]],
"害怕":["害: hại. 怕: sợ (bộ <b>忄</b> tâm). Sợ bị hại = sợ hãi.",["我妹妹害怕小狗。","Wǒ mèimei hàipà xiǎo gǒu.","Em gái tôi sợ chó con."]],
"生气":["生: sinh ra. 气: khí, hơi. Trong người sinh ra cục tức = giận.",["别生气了，我不是故意的。","Bié shēngqì le, wǒ bú shì gùyì de.","Đừng giận nữa, mình không cố ý."]],
"常见":["常: thường. 见: thấy. Thường thấy, thường gặp.",["这是一个很常见的问题。","Zhè shì yí ge hěn cháng jiàn de wèntí.","Đây là một vấn đề rất thường gặp."]],
"聪明":["聪: thính tai (bộ <b>耳</b>). 明: sáng mắt (日 + 月). Tai thính mắt sáng = thông minh.",["这个孩子很聪明。","Zhège háizi hěn cōngming.","Đứa trẻ này rất thông minh."]],
"错":["Bộ <b>钅</b> (kim loại) + 昔: đồng hồ, tiền nong lẫn lộn = sai. 做错, 写错, 出错.",["这个字你写错了。","Zhège zì nǐ xiěcuò le.","Chữ này bạn viết sai rồi."]],
"认为":["认: nhận (bộ <b>讠</b>). 为: là. Nhận định là = cho rằng.",["我认为这个办法很好。","Wǒ rènwéi zhège bànfǎ hěn hǎo.","Tôi cho rằng cách này rất hay."]],
"到处":["到: đến. 处: chỗ. Đến mọi chỗ = khắp nơi.",["春天到了，到处都是花。","Chūntiān dào le, dàochù dōu shì huā.","Mùa xuân đến, khắp nơi đều là hoa."]],
"继续":["继: nối (bộ <b>纟</b> sợi). 续: nối tiếp (bộ <b>纟</b>). Nối sợi tiếp = tiếp tục.",["休息一下，然后继续工作。","Xiūxi yíxià, ránhòu jìxù gōngzuò.","Nghỉ một lát rồi làm tiếp."]],
"同意":["同: cùng. 意: ý. Cùng một ý = đồng ý.",["妈妈同意我去中国留学。","Māma tóngyì wǒ qù Zhōngguó liúxué.","Mẹ đồng ý cho tôi đi du học Trung Quốc."]],
"可":["Khẩu ngữ = 可是: nhưng. Đứng đầu vế sau.",["我想去，可没有时间。","Wǒ xiǎng qù, kě méiyǒu shíjiān.","Mình muốn đi, nhưng không có thời gian."]],
"屋子":["屋: nhà, phòng (bộ <b>尸</b> mái che + 至 đến). 子: hậu tố. Căn phòng.",["这间屋子很干净。","Zhè jiān wūzi hěn gānjìng.","Căn phòng này rất sạch."]],
"有关":["有: có. 关: liên quan. 跟……有关: có liên quan đến ….",["这件事跟你有关。","Zhè jiàn shì gēn nǐ yǒuguān.","Việc này có liên quan đến bạn."]],
"关机":["关: đóng, tắt. 机: máy (bộ <b>木</b>). Tắt máy. Ngược lại: 开机.",["上课的时候请关机。","Shàngkè de shíhou qǐng guānjī.","Trong giờ học xin tắt máy."]],
"前天":["前: trước. 天: ngày. Ngày trước hôm qua = hôm kia. Ngược lại: 后天.",["我前天去了一趟超市。","Wǒ qiántiān qùle yí tàng chāoshì.","Hôm kia tôi đi siêu thị một chuyến."]],
"留学":["留: ở lại. 学: học. Ở lại nước ngoài học = du học. 留学生: lưu học sinh.",["她明年要去中国留学。","Tā míngnián yào qù Zhōngguó liúxué.","Năm sau cô ấy sẽ sang Trung Quốc du học."]],
"国家":["国: nước (bộ <b>囗</b> biên giới bao quanh). 家: nhà. Nhà của cả nước = quốc gia.",["你去过哪些国家？","Nǐ qùguo nǎxiē guójiā?","Bạn đã đi những nước nào?"]],
"比如":["比: so. 如: như. So như = ví dụ. Đứng trước các ví dụ.",["我喜欢吃水果，比如苹果、香蕉。","Wǒ xǐhuan chī shuǐguǒ, bǐrú píngguǒ, xiāngjiāo.","Tôi thích ăn hoa quả, ví dụ táo, chuối."]],
"查":["Bộ <b>木</b> trên + 旦: soi xét kỹ = tra, kiểm tra. 查词典: tra từ điển.",["这个字我不认识，我查一下。","Zhège zì wǒ bú rènshi, wǒ chá yíxià.","Chữ này tôi không biết, để tôi tra."]],
"有用":["有: có. 用: dùng. Có thể dùng được = hữu ích. Ngược lại: 没用.",["这本书对我很有用。","Zhè běn shū duì wǒ hěn yǒuyòng.","Quyển sách này rất có ích với tôi."]],
"容易":["容: chứa (bộ <b>宀</b>). 易: dễ. Dễ dàng. Ngược lại: 难.",["这个问题很容易。","Zhège wèntí hěn róngyì.","Câu hỏi này rất dễ."]],
"回答":["回: quay lại. 答: đáp (bộ <b>⺮</b> tre: thẻ tre ghi lời đáp). Đáp lại = trả lời.",["请回答我的问题。","Qǐng huídá wǒ de wèntí.","Xin hãy trả lời câu hỏi của tôi."]],
"方向":["方: phương. 向: hướng. Phương hướng.",["我们走错方向了。","Wǒmen zǒucuò fāngxiàng le.","Chúng ta đi sai hướng rồi."]],
"只有":["只: chỉ. 有: có. Chỉ có. 只有……才……: chỉ có … thì mới ….",["只有努力，才能成功。","Zhǐyǒu nǔlì, cái néng chénggōng.","Chỉ có cố gắng thì mới thành công."]],
"真正":["真: thật. 正: đúng. Thật sự, chân chính.",["他是我真正的朋友。","Tā shì wǒ zhēnzhèng de péngyou.","Anh ấy là người bạn thực sự của tôi."]],
"难题":["难: khó. 题: đề, câu hỏi (bộ <b>页</b>). Câu hỏi khó = vấn đề nan giải.",["这道数学题是个难题。","Zhè dào shùxué tí shì ge nántí.","Bài toán này là một bài khó."]]}});
